import type { Soru } from "../sorular";

export const P06: Soru[] = [
  { id: "p06-001", k: "Doğa", s: "Balıklar suda nefes almak için hangi organı kullanır?", d: "Solungaç", y: ["Akciğer", "Yüzgeç"], a: "Solungaçlar suda çözünmüş oksijeni kana geçirir. Su ağızdan girer, solungaçlardan geçip dışarı çıkar." },
  { id: "p06-002", k: "Doğa", s: "Köpekbalıklarının iskeleti çoğunlukla neyden oluşur?", d: "Kıkırdak", y: ["Kemik", "Kitin"], a: "Köpekbalıkları kıkırdaklı balıklardır. Kıkırdak kemikten hafif ve esnektir; kulak kepçemiz de kıkırdaktandır." },
  { id: "p06-003", k: "Doğa", s: "Dünyanın en büyük balığı hangisidir?", d: "Balina köpekbalığı", y: ["Büyük beyaz köpekbalığı", "Dev manta vatozu"], a: "Balina köpekbalığı bilinen en büyük balıktır. Adı \"balina\" olsa da bir köpekbalığıdır; balinalar ise memelidir." },
  { id: "p06-004", k: "Doğa", s: "Dev cüssesine rağmen balina köpekbalığı ne ile beslenir?", d: "Plankton ve küçük balıklar", y: ["Foklar ve yunuslar", "Deniz kaplumbağaları"], a: "Balina köpekbalığı kocaman ağzıyla suyu süzer ve plankton, balık yumurtası, küçük balık gibi minik canlıları yakalar." },
  { id: "p06-005", k: "Doğa", s: "Kemikli balıkların çoğunun suda batmadan dengede kalmasını sağlayan organ hangisidir?", d: "Yüzme kesesi", y: ["Solungaç kapağı", "Yan çizgi"], a: "Yüzme kesesi gazla dolu bir torbadır. Balık içindeki gaz miktarını ayarlayarak suda yükselir ya da alçalır." },
  { id: "p06-006", k: "Doğa", s: "Balıkların sudaki titreşimleri ve hareketleri algılamasını sağlayan duyu sistemi hangisidir?", d: "Yan çizgi", y: ["Yüzme kesesi", "Kuyruk yüzgeci"], a: "Yan çizgi, vücudun iki yanı boyunca uzanan duyu hücreleridir. Balık bununla yakındaki av, düşman ve sürü arkadaşlarının hareketini sezer." },
  { id: "p06-007", k: "Doğa", s: "Köpekbalıklarının canlıların ürettiği zayıf elektrik alanlarını algılamasını sağlayan organlara ne denir?", d: "Lorenzini ampulleri", y: ["Solungaç yarıkları", "Yan yüzgeçler"], a: "Lorenzini ampulleri burun çevresindeki jelle dolu küçük gözeneklerdir. Kumun altına gömülü avın kas hareketlerinden doğan elektriği bile sezebilir." },
  { id: "p06-008", k: "Doğa", s: "Bir köpekbalığının dişi döküldüğünde ne olur?", d: "Arkadan yenisi gelir", y: ["Bir daha diş çıkmaz", "Yalnız bir kez yenilenir"], a: "Köpekbalıklarının ağzında sıra sıra yedek diş bulunur. Ön dişler döküldükçe arkadakiler öne kayar, bu yüzden ömür boyu çok sayıda diş harcarlar." },
  { id: "p06-009", k: "Doğa", s: "Somonlar yumurtlamak için genellikle nereye göç eder?", d: "Doğdukları akarsulara", y: ["Okyanusun en derin yerlerine", "Mercan resiflerine"], a: "Somonlar yıllarını denizde geçirir, sonra yumurtlamak için doğdukları tatlı su akarsularına geri döner. Bu yolculukta akıntıya karşı yüzer." },
  { id: "p06-010", k: "Doğa", s: "Somonlar doğdukları akarsuyu bulurken en çok hangi duyularına güvenir?", d: "Koku", y: ["Tat", "Dokunma"], a: "Somonlar yavruyken doğdukları suyun kokusunu belleğe kaydeder. Yıllar sonra kıyıya yaklaşınca bu kokuyu izleyerek kendi akarsularını bulurlar." },
  { id: "p06-011", k: "Doğa", s: "Avrupa yılanbalığının yumurtlama alanı olarak bilinen deniz hangisidir?", d: "Sargasso Denizi", y: ["Karadeniz", "Baltık Denizi"], a: "Avrupa yılanbalıkları Atlas Okyanusu'ndaki Sargasso Denizi'nde doğar. Yavrular akıntılarla binlerce kilometre yol alıp Avrupa'nın akarsularına ulaşır." },
  { id: "p06-012", k: "Doğa", s: "Denizatlarında yumurtaları yavrular çıkana kadar hangisi taşır?", d: "Erkek", y: ["Dişi", "Sırayla ikisi"], a: "Dişi denizatı yumurtaları erkeğin karnındaki keseye bırakır. Erkek, yavrular çıkana kadar onları bu kesede taşır." },
  { id: "p06-013", k: "Doğa", s: "Palyaço balığı hangi canlının dokunaçları arasında güvenle yaşar?", d: "Deniz şakayığı", y: ["Deniz yıldızı", "Deniz kestanesi"], a: "Deniz şakayığının dokunaçları yakıcıdır ama palyaço balığının derisindeki mukus onu korur. Balık burada düşmanlarından saklanır." },
  { id: "p06-014", k: "Doğa", s: "Balon balığı tehlike sezdiğinde kendini nasıl korur?", d: "Su yutarak şişer", y: ["Mürekkep püskürtür", "Kuyruğunu koparır"], a: "Balon balığı hızla su yutup top gibi şişer. Böylece avcının ağzına sığmayacak kadar büyür." },
  { id: "p06-015", k: "Doğa", s: "Balon balıklarının birçoğunda bulunan çok güçlü zehrin adı nedir?", d: "Tetrodotoksin", y: ["Histamin", "Nikotin"], a: "Tetrodotoksin sinir sistemini felç eden çok güçlü bir zehirdir. Japonya'da fugu adıyla yenen balon balığını yalnız özel izinli aşçılar hazırlayabilir." },
  { id: "p06-016", k: "Doğa", s: "Elektrikli yılanbalığı hangi kıtanın tatlı sularında yaşar?", d: "Güney Amerika", y: ["Afrika", "Avustralya"], a: "Elektrikli yılanbalığı Amazon ve Orinoko havzalarında yaşar. Adına rağmen gerçek bir yılanbalığı değildir, bıçak balıklarının akrabasıdır." },
  { id: "p06-017", k: "Doğa", s: "Elektrikli yılanbalığı avını nasıl etkisiz hale getirir?", d: "Elektrik boşaltarak", y: ["Zehirli dikeniyle", "Mürekkep püskürterek"], a: "Vücudunun büyük kısmını kaplayan özel hücreler pil gibi dizilmiştir. Bunlar birlikte boşalınca avını sersemleten güçlü bir akım oluşur." },
  { id: "p06-018", k: "Doğa", s: "Akciğerli balıkları diğer balıklardan ayıran özellik nedir?", d: "Hava soluyabilmeleri", y: ["Işık saçabilmeleri", "Kanatlarıyla uçabilmeleri"], a: "Akciğerli balıklar akciğer benzeri organlarıyla havadan oksijen alabilir. Bazı türler kuraklıkta çamura gömülüp aylarca bekleyebilir." },
  { id: "p06-019", k: "Doğa", s: "Uçan balıklar sudan çıkınca havada nasıl ilerler?", d: "Geniş yüzgeçleriyle süzülerek", y: ["Kanat çırparak", "İçindeki gazla yükselerek"], a: "Uçan balıklar hızla yüzüp sudan fırlar, kanat gibi açtıkları göğüs yüzgeçleriyle süzülür. Böylece avcılardan kaçarlar." },
  { id: "p06-020", k: "Doğa", s: "Soyu tükendiği sanılan ve 1938'de Güney Afrika açıklarında canlı yakalanan balık hangisidir?", d: "Selakant", y: ["Mersin balığı", "Piranha"], a: "Selakantın yalnız fosillerden bilindiği ve dinozorlarla birlikte yok olduğu sanılıyordu. 1938'de bir balıkçı ağına canlı olarak takıldı." },
  { id: "p06-021", k: "Doğa", s: "Geleneksel havyar hangi balığın yumurtasından yapılır?", d: "Mersin balığı", y: ["Hamsi", "Sardalya"], a: "Gerçek havyar mersin balığının yumurtasıdır. Mersin balıkları yavaş büyüdüğü ve aşırı avlandığı için birçok türü tehlike altındadır." },
  { id: "p06-022", k: "Doğa", s: "Piranhalar doğal olarak hangi kıtanın akarsularında yaşar?", d: "Güney Amerika", y: ["Afrika", "Asya"], a: "Piranhalar Amazon başta olmak üzere Güney Amerika akarsularında yaşar. Filmlerdeki kadar saldırgan değildir; birçoğu leş ve küçük canlılarla beslenir." },
  { id: "p06-023", k: "Doğa", s: "Derin deniz fener balığı avını nasıl kendine çeker?", d: "Başındaki ışıklı uzantıyla", y: ["Yüksek sesler çıkararak", "Renkli yüzgeçlerini sallayarak"], a: "Fener balığının başındaki olta benzeri uzantının ucunda ışık saçan bakteriler yaşar. Karanlıkta parlayan bu yem küçük balıkları ağzına çeker." },
  { id: "p06-024", k: "Doğa", s: "Canlıların kimyasal tepkimeyle kendi ışığını üretmesine ne ad verilir?", d: "Biyolüminesans", y: ["Fotosentez", "Kemosentez"], a: "Biyolüminesans derin deniz canlılarında çok yaygındır. Ateşböceklerinin ışığı da aynı olayla oluşur." },
  { id: "p06-025", k: "Doğa", s: "Bazı derin deniz fener balığı türlerinde küçük erkek eşini bulunca ne yapar?", d: "Dişiye yapışıp onunla kaynaşır", y: ["Dişiyi yiyerek beslenir", "Yuvayı tek başına korur"], a: "Karanlık derinliklerde eş bulmak zordur. Bazı türlerde minik erkek dişiye ısırıp tutunur, zamanla kan dolaşımları birleşir." },
  { id: "p06-026", k: "Doğa", s: "Pisi ve kalkan gibi yassı balıklar büyürken gözlerinde ne olur?", d: "Bir göz diğer tarafa kayar", y: ["Gözleri tamamen körleşir", "İki göz kaynaşıp tek olur"], a: "Yassı balıklar normal balık gibi doğar. Büyürken bir gözleri başın öbür tarafına geçer ve iki göz de yukarı bakan yüzde kalır." },
  { id: "p06-027", k: "Doğa", s: "Bilim insanları bir balığın yaşını en çok neye bakarak tahmin eder?", d: "Kulak taşındaki halkalara", y: ["Yüzgeç sayısına", "Diş rengine"], a: "Kulak taşları (otolit) ağaçlar gibi her yıl yeni halka ekler. Bu halkalar sayılarak balığın yaşı tahmin edilir; pullardaki halkalar da kullanılır." },
  { id: "p06-028", k: "Doğa", s: "Yüzme kesesi olmayan köpekbalıklarının suda batmamasına en çok ne yardım eder?", d: "Yağlı büyük karaciğer", y: ["Akciğerdeki hava", "Kalın derisi"], a: "Köpekbalığının karaciğeri yağ bakımından zengindir ve sudan hafiftir. Bu da kıkırdaklı iskeletle birlikte batmasını zorlaştırır." },
  { id: "p06-029", k: "Doğa", s: "Köpekbalığı derisine zımpara gibi pürüzlü bir doku veren yapılar nelerdir?", d: "Dişe benzeyen minik pullar", y: ["İnce tüyler", "Kemik plakalar"], a: "Köpekbalığı derisi dişe benzeyen küçük pullarla kaplıdır. Bu pullar sudaki sürtünmeyi de azaltır." },
  { id: "p06-030", k: "Doğa", s: "Çekiç başlı köpekbalığının gözleri nerede bulunur?", d: "Başının iki uç kenarında", y: ["Başının tam ortasında", "Ağzının altında"], a: "Gözlerin geniş başın iki ucunda olması köpekbalığına geniş bir görüş alanı sağlar." },
  { id: "p06-031", k: "Doğa", s: "Büyük beyaz köpekbalığı gibi bazı türler solungaçlarına su göndermek için ne yapmak zorundadır?", d: "Sürekli yüzmek", y: ["Su yüzüne çıkmak", "Ağzını kapalı tutmak"], a: "Bu türler ağızları açık yüzerek solungaçlarından su geçirir. Durursa yeterli oksijen alamaz; bazı köpekbalıkları ise dururken de su pompalayabilir." },
  { id: "p06-032", k: "Doğa", s: "Soğuk kuzey denizlerinde yaşayan Grönland köpekbalığı neyle ünlüdür?", d: "Çok uzun ömrüyle", y: ["Çok hızlı yüzmesiyle", "Renk değiştirmesiyle"], a: "Bir araştırmaya göre Grönland köpekbalıkları yüzyıllarca yaşayabilir. Bu da onları bilinen en uzun ömürlü omurgalılardan biri yapar." },
  { id: "p06-033", k: "Doğa", s: "Köpekbalıkları hangi hayvan grubuna aittir?", d: "Balıklar", y: ["Memeliler", "Sürüngenler"], a: "Köpekbalıkları solungaçla nefes alan kıkırdaklı balıklardır. Yunus ve balinalar ise akciğerle nefes alan memelilerdir." },
  { id: "p06-034", k: "Doğa", s: "Vatozlarla köpekbalıklarının ortak özelliği hangisidir?", d: "Kıkırdaklı iskelet", y: ["Akciğerle solunum", "Sert kabuk"], a: "Vatozlar köpekbalıklarının yakın akrabasıdır ve onlar gibi kıkırdaklı balıklar grubundadır. Yassı gövdeleri ve kanat gibi yüzgeçleriyle tanınırlar." },
  { id: "p06-035", k: "Doğa", s: "Dev manta vatozu ne ile beslenir?", d: "Plankton", y: ["Mercan", "Deniz kaplumbağası"], a: "Mantalar ağızlarını açıp suyu süzer, içindeki planktonu yakalar. Büyük olmalarına karşın insanlar için zararsızdırlar." },
  { id: "p06-036", k: "Doğa", s: "Torpil balığı kendini korumak ve avlanmak için ne kullanır?", d: "Elektrik şoku", y: ["Zehirli diken", "Mürekkep bulutu"], a: "Torpil balıkları elektrikli vatozlardır. Vücutlarındaki özel organlarla avlarını sersemletecek kadar elektrik üretebilirler." },
  { id: "p06-037", k: "Doğa", s: "Dikenli vatozların kuyruğunda ne bulunur?", d: "Zehirli bir diken", y: ["Işık organı", "Yapışkan vantuz"], a: "Dikenli vatoz kuyruğundaki zehirli dikeni yalnız tehlikede, kendini korumak için kullanır. Kuma gömülü vatoza basmamak için sığ suda ayak sürüyerek yürümek önerilir." },
  { id: "p06-038", k: "Doğa", s: "Japon balıklarıyla yapılan deneyler hafızaları hakkında ne gösteriyor?", d: "Aylarca hatırlayabiliyorlar", y: ["3 saniyede unutuyorlar", "Hiçbir şey öğrenemiyorlar"], a: "\"3 saniyelik hafıza\" bir efsanedir. Deneylerde japon balıkları bir sesi ya da rengi yemle ilişkilendirmeyi öğrenmiş ve aylar sonra bile hatırlamıştır." },
  { id: "p06-039", k: "Doğa", s: "Japon balığı ilk kez hangi ülkede evcilleştirildi?", d: "Çin", y: ["Brezilya", "Mısır"], a: "Japon balığı Çin'de yabani sazan akrabalarından seçilerek yüzyıllar önce evcilleştirildi. Daha sonra Japonya'ya ve dünyaya yayıldı." },
  { id: "p06-040", k: "Doğa", s: "Balıkların çoğunda vücut sıcaklığını ne belirler?", d: "Çevredeki suyun sıcaklığı", y: ["Sabit 37 derece", "Yedikleri besin"], a: "Balıkların çoğu soğukkanlıdır; vücut sıcaklıkları suyunkine yakındır. Orkinos gibi birkaç tür vücudunun bazı bölgelerini sudan sıcak tutabilir." },
  { id: "p06-041", k: "Doğa", s: "Sardalya gibi küçük balıklar neden kalabalık sürüler halinde yüzer?", d: "Avcılardan korunmak için", y: ["Suyu ısıtmak için", "Uyuyabilmek için"], a: "Sürüde tek bir balığı hedeflemek zordur. Binlerce balığın aynı anda dönmesi avcının kafasını karıştırır." },
  { id: "p06-042", k: "Doğa", s: "Kemikli balıklarda solungaçları dışarıdan örten yapıya ne denir?", d: "Solungaç kapağı", y: ["Sırt yüzgeci", "Yan çizgi"], a: "Solungaç kapağı narin solungaçları korur ve açılıp kapanarak suyun akmasına yardım eder. Köpekbalıklarında bu kapak yoktur, solungaç yarıkları dışarıdan görünür." },
  { id: "p06-043", k: "Doğa", s: "Okçu balığı su üstündeki böcekleri nasıl avlar?", d: "Ağzından su fışkırtarak", y: ["Havaya zıplayarak", "Elektrik akımıyla"], a: "Okçu balığı dallara konan böceklere ağzından su püskürtür. Suya düşen böceği hemen yakalar." },
  { id: "p06-044", k: "Doğa", s: "Çamur zıpzıpı balığı neyle bilinir?", d: "Karada uzun süre kalabilmesiyle", y: ["Çok derin sularda yaşamasıyla", "Işık saçmasıyla"], a: "Çamur zıpzıpları gelgit bölgelerinde yüzgeçleriyle çamurda sürünür ve zıplar. Derileri ve ağızlarıyla da havadan oksijen alabilirler." },
  { id: "p06-045", k: "Doğa", s: "Çenesi olmayan balıklara örnek hangisidir?", d: "Taşemen (lamprey)", y: ["Alabalık", "Levrek"], a: "Taşemenlerin çenesi yoktur; ağızları vantuz gibidir. Bazı türler bu ağızla başka balıklara tutunup kanlarını emer." },
  { id: "p06-046", k: "Doğa", s: "Hangisi bir tatlı su balığıdır?", d: "Sazan", y: ["Hamsi", "Lüfer"], a: "Sazan göl ve akarsularda yaşayan bir tatlı su balığıdır. Hamsi ve lüfer ise deniz balıklarıdır." },
  { id: "p06-047", k: "Doğa", s: "Van Gölü'nün sodalı sularına uyum sağlamış balık hangisidir?", d: "İnci kefali", y: ["Gökkuşağı alabalığı", "Lüfer"], a: "İnci kefali (tarek) Van Gölü'nün sodalı suyunda yaşayabilen tek balık olarak bilinir. Yumurtlamak için göle dökülen tatlı su akarsularına göç eder." },
  { id: "p06-048", k: "Doğa", s: "Balıkların çoğu yüzerken asıl itiş gücünü nereden alır?", d: "Kuyruk yüzgecinden", y: ["Göğüs yüzgeçlerinden", "Solungaçlarından"], a: "Balıklar gövdelerini ve kuyruklarını iki yana kıvırarak ilerler. Diğer yüzgeçler daha çok yön değiştirmeye ve dengeye yarar." },
  { id: "p06-049", k: "Doğa", s: "Lepistes (guppy) balıkları yavrularını nasıl dünyaya getirir?", d: "Canlı doğurarak", y: ["Yuvaya yumurta bırakarak", "Bölünerek çoğalarak"], a: "Lepistesler yumurtaları vücutlarında taşır ve yavruları yüzebilir halde doğurur. Bu yüzden akvaryumda çok hızlı çoğalırlar." },
  { id: "p06-050", k: "Doğa", s: "Beta balığı su yüzeyinden hava almak için hangi organını kullanır?", d: "Labirent organı", y: ["Yüzme kesesi", "Yan çizgi"], a: "Labirent organı solungaçların üstünde, kıvrımlı bir yapıdır. Beta balığı bununla oksijeni az olan durgun sularda da yaşayabilir." },
  { id: "p06-051", k: "Doğa", s: "Erkek beta balığı yumurtalar için nasıl bir yuva yapar?", d: "Köpükten yuva", y: ["Taşlardan yuva", "Yosundan top"], a: "Erkek beta su yüzeyinde tükürüklü hava kabarcıklarıyla köpük yuva yapar. Yumurtaları bu yuvaya yerleştirip korur." },
  { id: "p06-052", k: "Doğa", s: "Pasifik somonlarının çoğuna yumurtladıktan sonra ne olur?", d: "Kısa süre içinde ölür", y: ["Denize dönüp yeniden yumurtlar", "Kış uykusuna yatar"], a: "Pasifik somonları göç sırasında neredeyse hiç beslenmez ve yumurtladıktan sonra ölür. Bedenleri akarsudaki birçok canlıya besin olur." },
  { id: "p06-053", k: "Doğa", s: "Taş balığı neyle tanınır?", d: "Çok zehirli dikenleriyle", y: ["Elektrik üretmesiyle", "Işık saçmasıyla"], a: "Taş balığı kayaya çok benzer, bu yüzden fark edilmesi zordur. Sırtındaki dikenlerin zehri dünyanın en tehlikeli balık zehirlerinden sayılır." },
  { id: "p06-054", k: "Doğa", s: "İstilacı aslan balığı Kızıldeniz'den Akdeniz'e hangi yolla geçti?", d: "Süveyş Kanalı", y: ["Cebelitarık Boğazı", "İstanbul Boğazı"], a: "Süveyş Kanalı açıldıktan sonra Kızıldeniz'den yüzlerce tür Akdeniz'e geçti. Zehirli dikenli aslan balığı da bunlardan biridir." },
  { id: "p06-055", k: "Doğa", s: "Temizlikçi balıklar resiflerde ne iş görür?", d: "Diğer balıkların parazitlerini yer", y: ["Mercanları budar", "Kumları eler"], a: "Temizlikçi balıkların olduğu yerlere büyük balıklar gelir ve ağızlarını açıp bekler. Temizlikçi parazitleri yerken diğer balık da temizlenmiş olur." },
  { id: "p06-056", k: "Doğa", s: "Remora balığı başındaki vantuz benzeri yapıyı ne için kullanır?", d: "Büyük hayvanlara tutunmak", y: ["Avını zehirlemek", "Kumu kazmak"], a: "Remora köpekbalığı, vatoz ve kaplumbağa gibi büyük hayvanlara tutunup onlarla yolculuk eder. Artık yemeklerle ve parazitlerle beslenir." },
  { id: "p06-057", k: "Doğa", s: "Papağan balıkları mercan resiflerinde neyin oluşumuna katkı sağlar?", d: "Beyaz kum", y: ["Deniz tuzu", "Yosun adaları"], a: "Papağan balıkları mercan üzerindeki algleri kemirirken mercan parçalarını da yutar. Bunlar sindirim yoluyla ince kum olarak dışarı atılır." },
  { id: "p06-058", k: "Doğa", s: "Bazı papağan balıkları geceleri kendilerini neyle sarar?", d: "Sümükten bir koza", y: ["Deniz yosunu", "Kum tabakası"], a: "Bazı papağan balıkları uyumadan önce ağızlarından salgıladıkları mukustan bir koza örer. Bu kozanın koku yayılmasını azaltıp parazitlere karşı koruduğu düşünülür." },
  { id: "p06-059", k: "Doğa", s: "Yassı, yuvarlak gövdesiyle bilinen ve en ağır kemikli balıklardan olan tür hangisidir?", d: "Ay balığı", y: ["Kılıç balığı", "Turna balığı"], a: "Ay balığı (Mola) bir tona yaklaşan, hatta aşan ağırlığa ulaşabilir. Kuyruğu kısadır ve büyük ölçüde denizanası gibi yumuşak canlılarla beslenir." },
  { id: "p06-060", k: "Doğa", s: "Mavi yüzgeçli orkinosu çoğu balıktan ayıran özellik hangisidir?", d: "Vücudunu sudan sıcak tutabilmesi", y: ["Akciğerle nefes alması", "Canlı doğurması"], a: "Orkinos özel bir damar düzeniyle kaslarının ürettiği ısıyı korur. Bu sayede soğuk sularda da hızlı ve güçlü yüzebilir." },
  { id: "p06-061", k: "Doğa", s: "Köpekbalıkları dinozorlara göre ne zaman ortaya çıktı?", d: "Dinozorlardan çok önce", y: ["Dinozorlardan sonra", "Dinozorlarla aynı anda"], a: "En eski köpekbalığı fosilleri yaklaşık 400 milyon yıl öncesine uzanır. İlk dinozorlar ise yaklaşık 230 milyon yıl önce ortaya çıktı." },
  { id: "p06-062", k: "Doğa", s: "Megalodon nedir?", d: "Soyu tükenmiş dev köpekbalığı", y: ["Bir dinozor türü", "Dev bir balina"], a: "Megalodon milyonlarca yıl önce okyanuslarda yaşamış çok büyük bir köpekbalığıdır. Bugün soyu tükenmiştir." },
  { id: "p06-063", k: "Doğa", s: "Megalodon hakkındaki bilgiler en çok hangi fosillerden gelir?", d: "Dişlerinden", y: ["Tam iskeletlerinden", "Ayak izlerinden"], a: "Köpekbalığı iskeleti kıkırdak olduğu için kolay fosilleşmez. Megalodon'dan geriye en çok el büyüklüğündeki dişleri kalmıştır." },
  { id: "p06-064", k: "Doğa", s: "Kaplan köpekbalığı neyle tanınır?", d: "Neredeyse her şeyi yemesiyle", y: ["Yalnız plankton yemesiyle", "Tatlı suda yaşamasıyla"], a: "Kaplan köpekbalıkları balık, kaplumbağa, deniz kuşu ve leş yer. Midelerinden plaka, lastik gibi tuhaf nesneler de çıkmıştır." },
  { id: "p06-065", k: "Doğa", s: "Boğa köpekbalığını diğer köpekbalıklarının çoğundan ayıran özellik nedir?", d: "Tatlı suya girebilmesi", y: ["Kara üzerinde yürüyebilmesi", "Işık saçması"], a: "Boğa köpekbalıkları tuz dengelerini ayarlayabildiği için nehirlere girip kilometrelerce yol alabilir. Amazon ve Mississippi'de görüldükleri bilinir." },
  { id: "p06-066", k: "Doğa", s: "Köpekbalıklarının üremesi için hangisi doğrudur?", d: "Bazıları yumurtlar, bazıları doğurur", y: ["Tamamı yalnız yumurtlar", "Tamamı yalnız doğurur"], a: "Bazı köpekbalıkları sert kapsüllü yumurtalar bırakır. Birçok tür ise yavrularını anne karnında büyütüp canlı doğurur." },
  { id: "p06-067", k: "Doğa", s: "Yayın balığının ağzı çevresindeki bıyık benzeri uzantılar ne işe yarar?", d: "Tat ve dokunma algısına", y: ["Avı zehirlemeye", "Nefes almaya"], a: "Bu uzantılarda tat alıcıları bulunur. Yayın balıkları bulanık suda ve dipte besinlerini bu bıyıklarla bulur." },
  { id: "p06-068", k: "Doğa", s: "Bir palyaço balığı grubunda baskın dişi ölünce ne olur?", d: "En büyük erkek dişiye dönüşür", y: ["Grup dağılıp ölür", "Yavrular yeni dişi seçer"], a: "Palyaço balıkları erkek olarak başlar. Gruptaki dişi ölünce en büyük erkek dişiye dönüşür ve onun yerini alır." },
  { id: "p06-069", k: "Doğa", s: "Meksika mağaralarında yaşayan bazı tetra balıklarında hangi özellik gelişmiştir?", d: "Gözlerini yitirmişlerdir", y: ["Işık saçarlar", "Karada yürürler"], a: "Karanlık mağaralarda göz işe yaramaz. Bu balıklar zamanla gözlerini ve rengini yitirmiş, yönlerini yan çizgi gibi duyularla bulur hale gelmiştir." },
  { id: "p06-070", k: "Doğa", s: "Balıklar ses duyabilir mi?", d: "Evet, iç kulakları vardır", y: ["Hayır, hiç duyamazlar", "Yalnız su yüzündeyken"], a: "Balıkların dışarıdan görünmeyen iç kulakları vardır. Su sesi havadan iyi ilettiği için birçok balık sesle haberleşir." },
  { id: "p06-071", k: "Doğa", s: "Zebra balığı laboratuvarlarda neden çok kullanılır?", d: "Embriyosu saydam olduğu için", y: ["Çok uzun yaşadığı için", "Hiç hastalanmadığı için"], a: "Zebra balığı embriyoları saydamdır, organların gelişimi canlı canlı izlenebilir. Hızlı ürediği için de yaygın bir deney canlısıdır." },
  { id: "p06-072", k: "Doğa", s: "Zebra balığı hangi organındaki hasarı onarabilmesiyle bilinir?", d: "Kalp", y: ["Mide", "Göz merceği"], a: "Zebra balığı kalbinin hasar gören bölümünü yeniden oluşturabilir. Bilim insanları bunu insan kalbini onarma yollarını anlamak için inceliyor." },
  { id: "p06-073", k: "Doğa", s: "Victoria Gölü'ne sonradan getirilen ve yerli balıkların birçoğunu yok eden tür hangisidir?", d: "Nil levreği", y: ["Japon balığı", "Somon"], a: "Nil levreği 1950'lerde balıkçılık için göle bırakıldı. Bu iri avcı, gölün yerli çiklit balıklarının pek çok türünün yok olmasına yol açtı." },
  { id: "p06-074", k: "Doğa", s: "Alabalıklar genellikle nasıl suları sever?", d: "Soğuk ve oksijeni bol", y: ["Sıcak ve durgun", "Tuzlu ve bulanık"], a: "Alabalıklar soğuk, temiz ve akıntılı suları sever. Soğuk su daha çok oksijen tutar." },
  { id: "p06-075", k: "Doğa", s: "Deniz balıkları vücutlarına giren fazla tuzu en çok nasıl atar?", d: "Solungaçlarından dışarı atarak", y: ["Pullarından terleyerek", "Hiç tuz almayarak"], a: "Deniz balıkları sürekli tuzlu su içer. Fazla tuzu solungaçlarındaki özel hücrelerle dışarı pompalar." },
  { id: "p06-076", k: "Doğa", s: "Tatlı su balıkları vücutlarına giren fazla suyu nasıl atar?", d: "Bol ve seyreltik idrarla", y: ["Ağızlarından püskürterek", "Pullarından buharlaştırarak"], a: "Tatlı suda vücuda sürekli su sızar. Balık bu fazlalığı bol miktarda sulu idrarla atar, tuzu ise solungaçlarıyla dışarıdan toplar." },
  { id: "p06-077", k: "Doğa", s: "Kılıç balığı burnundaki uzun \"kılıcı\" ne için kullanır?", d: "Avını yaralayıp sersemletmek", y: ["Kumda yuva kazmak", "Eşine kur yapmak"], a: "Kılıç balığı sürünün içine dalıp kılıcını iki yana savurur. Yaralanan ya da sersemleyen balıkları sonra rahatça yakalar." },
  { id: "p06-078", k: "Doğa", s: "Yelken balığı adını neyinden alır?", d: "Büyük sırt yüzgecinden", y: ["Uzun kuyruğundan", "Geniş solungaçlarından"], a: "Yelken balığının sırtında yelkene benzeyen kocaman bir yüzgeç vardır. Avlanırken bu yüzgeci açıp kapatabilir." },
  { id: "p06-079", k: "Doğa", s: "Denizatları suda nasıl yüzer?", d: "Dik durup sırt yüzgeciyle", y: ["Kuyruğunu çırparak hızla", "Su püskürterek"], a: "Denizatı dik durur ve küçük sırt yüzgecini hızla titreterek yavaşça ilerler. Kıvrık kuyruğuyla da yosunlara tutunur." },
  { id: "p06-080", k: "Doğa", s: "Denizatı hangi hayvan grubuna aittir?", d: "Balıklar", y: ["Yumuşakçalar", "Eklembacaklılar"], a: "Denizatı görünüşüne rağmen solungaçlı, yüzgeçli bir kemikli balıktır." },
  { id: "p06-081", k: "Doğa", s: "Yapraklı deniz ejderi düşmanlarından nasıl korunur?", d: "Yosuna benzeyerek", y: ["Elektrik üreterek", "Zehir tükürerek"], a: "Avustralya kıyılarında yaşayan bu denizatı akrabasının vücudu yaprak gibi uzantılarla kaplıdır. Yosunların arasında neredeyse görünmez olur." },
  { id: "p06-082", k: "Doğa", s: "Balina köpekbalıklarını birbirinden ayırmak için ne kullanılır?", d: "Derilerindeki benek desenleri", y: ["Yüzgeç sayıları", "Çıkardıkları sesler"], a: "Her balina köpekbalığının benek deseni insan parmak izi gibi kendine özgüdür. Araştırmacılar fotoğraflardan bireyleri bu desenle tanır." },
  { id: "p06-083", k: "Doğa", s: "Balıklardan kara hayvanlarına geçişi gösteren ünlü fosil hangisidir?", d: "Tiktaalik", y: ["Arkeopteriks", "Trilobit"], a: "Tiktaalik yaklaşık 375 milyon yıl önce yaşamış bir balıktır. Hem solungacı hem de bileğe benzer kemikli yüzgeçleri vardı." },
  { id: "p06-084", k: "Doğa", s: "Balıkların vücudunu örten ve koruyan ince plakalara ne denir?", d: "Pul", y: ["Tüy", "Kabuk"], a: "Pullar balığı yaralanmaya ve hastalığa karşı korur. Üzerlerindeki mukus tabakası da suda kaymayı kolaylaştırır." },
  { id: "p06-085", k: "Doğa", s: "Pisi balığı ve kalkan hangi ortamda yaşar?", d: "Deniz dibinde", y: ["Su yüzeyinde", "Mağara göllerinde"], a: "Yassı balıklar yan yatarak deniz dibinde yaşar. Bazı türler rengini zemine uydurup kumun altına gizlenebilir." },
  { id: "p06-086", k: "Doğa", s: "Mürekkep bulutu bırakıp kaçan \"mürekkep balığı\" aslında hangi gruptadır?", d: "Yumuşakçalar", y: ["Kemikli balıklar", "Kıkırdaklı balıklar"], a: "Mürekkep balığı adında \"balık\" geçse de ahtapot ve kalamarın akrabası bir yumuşakçadır." },
  { id: "p06-087", k: "Doğa", s: "Sazan ve japon balığının mide yapısında dikkat çeken özellik nedir?", d: "Gerçek bir mideleri yoktur", y: ["İki mideleri vardır", "Mideleri taş doludur"], a: "Sazangillerde ayrı bir mide yoktur; yemek yemek borusundan doğrudan bağırsağa geçer. Bu yüzden azar azar ve sık beslenirler." },
  { id: "p06-088", k: "Doğa", s: "Hamsi Türkiye'de en çok hangi denizle özdeşleşmiştir?", d: "Karadeniz", y: ["Ege Denizi", "Akdeniz"], a: "Hamsi Karadeniz mutfağının simgesidir. Kışın Karadeniz'in Türkiye kıyılarında yoğun avlanır." },
  { id: "p06-089", k: "Doğa", s: "Kirpi balığını balon balığından ayıran en belirgin özellik nedir?", d: "Şişince dikilen uzun dikenleri", y: ["Elektrik üretmesi", "Bacaklarının olması"], a: "Kirpi balığı da şişebilir ama vücudu uzun dikenlerle kaplıdır. Şişince dikenler dikilir ve onu yutulması zor bir top haline getirir." },
  { id: "p06-090", k: "Doğa", s: "Birçok balık türü nasıl ürer?", d: "Suya yumurta bırakarak", y: ["Tomurcuklanarak", "İkiye bölünerek"], a: "Balıkların çoğu suya çok sayıda yumurta bırakır ve bunlar dışarıda döllenir. Yumurtaların ancak küçük bir kısmı ergin balık olabilir." },
  { id: "p06-091", k: "Doğa", s: "Balıkların kalbi kaç odacıklıdır?", d: "İki", y: ["Dört", "Bir"], a: "Balık kalbinde bir kulakçık ve bir karıncık bulunur. Kan kalpten solungaçlara, oradan da tüm vücuda gider." },
  { id: "p06-092", k: "Doğa", s: "Köpekbalıkları avlarını uzaktan en çok hangi duyuyla fark eder?", d: "Koku", y: ["Görme", "Tat"], a: "Köpekbalıklarının koku duyusu çok gelişmiştir. Sudaki çok az miktardaki kanı ya da balık kokusunu uzaktan sezebilirler." },
  { id: "p06-093", k: "Doğa", s: "Mersin balıklarının sırtında ve yanlarında ne bulunur?", d: "Kemikli plaka sıraları", y: ["Uzun zehirli dikenler", "Işık saçan noktalar"], a: "Mersin balıklarının pulları yerine gövde boyunca sıralanmış sert kemik plakalar vardır. Çok eski bir balık grubu oldukları için \"yaşayan fosil\" de denir." },
  { id: "p06-094", k: "Doğa", s: "Çekiç başlı köpekbalığının başının geniş olması ona ne kazandırır?", d: "Daha geniş görüş ve algı", y: ["Daha hızlı yüzme", "Su dışında nefes"], a: "Geniş baş, gözler arasındaki mesafeyi açar ve elektrik algılayan gözeneklere geniş bir alan sağlar. Böylece kuma gömülü avı daha kolay bulur." },
  { id: "p06-095", k: "Doğa", s: "Köpekbalıklarında solungaçlar dışarıdan nasıl görünür?", d: "Yan yana yarıklar halinde", y: ["Tek bir kapağın altında", "Hiç görünmez"], a: "Köpekbalıklarının başının iki yanında genellikle beş ile yedi arası solungaç yarığı bulunur. Kemikli balıklardaki gibi bir kapakları yoktur." },
  { id: "p06-096", k: "Doğa", s: "Yılanbalıkları denizde doğup tatlı suya çıkarken ilk evrelerinde nasıl görünür?", d: "Saydam ve ince", y: ["Yuvarlak ve dikenli", "Kırmızı ve pullu"], a: "Yavru yılanbalıkları kıyıya yaklaştıklarında cam gibi saydamdır, bu yüzden \"cam yılanbalığı\" denir. Tatlı suda büyüdükçe renklenirler." },
  { id: "p06-097", k: "Doğa", s: "Balıkların vücudunu kaplayan mukus (sümük) tabakası ne işe yarar?", d: "Mikroplara karşı korur", y: ["Işık saçmasını sağlar", "Nefes almasını sağlar"], a: "Mukus tabakası balığı bakteri, mantar ve parazitlere karşı korur. Suyla sürtünmeyi de azaltır." },
  { id: "p06-098", k: "Doğa", s: "Okyanusun derinliklerinde yaşayan balıkların çoğunda hangi renkler yaygındır?", d: "Siyah ya da kırmızı", y: ["Parlak sarı", "Beyaz ve mavi"], a: "Kırmızı ışık derin sulara ulaşmaz, bu yüzden kırmızı renkli bir balık orada siyah gibi görünür. Bu da onları gizler." },
  { id: "p06-099", k: "Doğa", s: "Bir ahtapotun kaç kolu vardır?", d: "8", y: ["6", "10"], a: "Ahtapotun sekiz kolu vardır ve her kolda yüzlerce vantuz bulunur. Adı da Yunanca \"sekiz ayak\" anlamına gelir." },
  { id: "p06-100", k: "Doğa", s: "Bir ahtapotun kaç kalbi vardır?", d: "3", y: ["1", "2"], a: "İki kalp kanı solungaçlara pompalar, üçüncüsü vücudun geri kalanına gönderir." },
  { id: "p06-101", k: "Doğa", s: "Ahtapot kanı ne renktir?", d: "Mavi", y: ["Kırmızı", "Yeşil"], a: "Ahtapot kanında oksijeni bakır içeren bir protein taşır. Bu protein oksijenle birleşince kana mavi renk verir." },
  { id: "p06-102", k: "Doğa", s: "Ahtapot ve yengeç kanına mavi rengi veren bakırlı protein hangisidir?", d: "Hemosiyanin", y: ["Hemoglobin", "Klorofil"], a: "Bizim kanımızdaki hemoglobin demir içerir ve kırmızıdır. Hemosiyanin ise bakır içerir ve oksijen bağlayınca mavi görünür." },
  { id: "p06-103", k: "Doğa", s: "Ahtapotlar tehlikede kaçarken arkalarında ne bırakır?", d: "Mürekkep bulutu", y: ["Zehirli köpük", "Işıklı sıvı"], a: "Koyu mürekkep bulutu avcının görüşünü kapatır ve kafasını karıştırır. Ahtapot bu arada hızla uzaklaşır." },
  { id: "p06-104", k: "Doğa", s: "Ahtapotlar derilerinin rengini hangi hücrelerle değiştirir?", d: "Kromatofor", y: ["Alyuvar", "Trombosit"], a: "Kromatoforlar renk maddesi dolu küçük keseciklerdir. Kaslar bu keseleri açıp kapatarak deri rengini saniyeler içinde değiştirir." },
  { id: "p06-105", k: "Doğa", s: "Ahtapotun çok dar deliklerden geçebilmesinin başlıca nedeni nedir?", d: "Kemiksiz yumuşak vücudu", y: ["Kolunu koparıp bırakması", "Kendini sıvılaştırması"], a: "Ahtapotun iskeleti yoktur. Vücudundaki tek sert kısım gagası olduğu için gagasının sığdığı her delikten geçebilir." },
  { id: "p06-106", k: "Doğa", s: "Ahtapotun yakın akrabası olan hayvan hangisidir?", d: "Salyangoz", y: ["Yengeç", "Deniz yıldızı"], a: "Ahtapot da salyangoz gibi bir yumuşakçadır. Yengeç eklembacaklı, deniz yıldızı ise derisidikenlidir." },
  { id: "p06-107", k: "Doğa", s: "Ahtapot, kalamar ve mürekkep balığını içeren hayvan grubu hangisidir?", d: "Kafadanbacaklılar", y: ["Derisidikenliler", "Kabuklular"], a: "Bu hayvanlarda kollar doğrudan başa bağlıdır, grup adı da buradan gelir. Hepsi yumuşakçalar şubesindedir." },
  { id: "p06-108", k: "Doğa", s: "Avustralya çevresinde yaşayan ve küçük boyuna rağmen çok zehirli olan ahtapot hangisidir?", d: "Mavi halkalı ahtapot", y: ["Pasifik dev ahtapotu", "Taklitçi ahtapot"], a: "Mavi halkalı ahtapot avuç içi kadardır ama tükürüğünde tetrodotoksin bulunur. Tehlike sezince derisindeki mavi halkalar parlar." },
  { id: "p06-109", k: "Doğa", s: "Ahtapotun sinir hücrelerinin çoğu nerede bulunur?", d: "Kollarında", y: ["Beyninde", "Gözlerinde"], a: "Ahtapot sinir hücrelerinin büyük bölümü kollarına dağılmıştır. Bu yüzden kollar birçok hareketi kendi başına yönetebilir." },
  { id: "p06-110", k: "Doğa", s: "Hayvanlar aleminin en büyük gözleri hangi canlılarda bulunur?", d: "Dev ve devasa kalamarlarda", y: ["Mavi balinalarda", "Fillerde"], a: "Dev kalamar ve devasa kalamarın gözleri bir futbol topu kadar olabilir. Bu gözler karanlık derinliklerdeki az ışığı yakalamaya yarar." },
  { id: "p06-111", k: "Doğa", s: "Bilinen en ağır omurgasız hayvan hangisidir?", d: "Devasa kalamar", y: ["Japon örümcek yengeci", "Pasifik dev ahtapotu"], a: "Antarktika sularında yaşayan devasa kalamarın ağırlığı yarım tona yaklaşabilir. Bilinen en ağır omurgasız odur." },
  { id: "p06-112", k: "Doğa", s: "Bir kalamarın kaç kolu ve uzun dokunacı vardır?", d: "8 kol ve 2 dokunaç", y: ["6 kol ve 4 dokunaç", "10 kol ve dokunaçsız"], a: "Kalamarın sekiz kolunun yanında av yakalamaya yarayan iki uzun dokunacı vardır. Ahtapotlarda bu iki dokunaç bulunmaz." },
  { id: "p06-113", k: "Doğa", s: "Kafes kuşlarına kalsiyum için verilen \"sepya kemiği\" hangi hayvandan gelir?", d: "Mürekkep balığı", y: ["Köpekbalığı", "Yengeç"], a: "Mürekkep balığının içinde gözenekli, hafif bir kabuk bulunur. Hayvan bu kabukla suda batmasını ve yükselmesini ayarlar." },
  { id: "p06-114", k: "Doğa", s: "Nautilus'u diğer yaşayan kafadanbacaklılardan ayıran özellik nedir?", d: "Dışında odacıklı bir kabuk taşıması", y: ["Sekizden az kolu olması", "Karada yaşaması"], a: "Nautilus helezon biçimli, odacıklara bölünmüş bir kabuk taşır. Odacıklardaki gaz ve sıvıyı ayarlayarak suda yükselip alçalır." },
  { id: "p06-115", k: "Doğa", s: "Birçok ahtapot türünde dişi yumurtaları için ne yapar?", d: "Yumurtalar çıkana dek başında bekler", y: ["Yumurtaları yutup taşır", "Yumurtaları kıyıya gömer"], a: "Dişi ahtapot yumurtalarını temizler, havalandırır ve korur. Bu sürede çoğu zaman beslenmez ve yavrular çıktıktan kısa süre sonra ölür." },
  { id: "p06-116", k: "Doğa", s: "Bir denizanasının vücudunun yaklaşık ne kadarı sudur?", d: "%95", y: ["%50", "%70"], a: "Denizanalarının vücudu yaklaşık yüzde 95 sudur. Karaya vurduklarında bu yüzden hızla kuruyup küçülürler." },
  { id: "p06-117", k: "Doğa", s: "Denizanalarında beyin yerine ne bulunur?", d: "Sinir ağı", y: ["Omurilik", "İki küçük beyin"], a: "Denizanalarının beyni yoktur. Vücutlarına yayılmış bir sinir ağı ışık, dokunma ve hareket gibi uyarılara tepki vermelerini sağlar." },
  { id: "p06-118", k: "Doğa", s: "Denizanasının yakıcı olmasını sağlayan hücrelere ne denir?", d: "Knidosit (yakıcı hücre)", y: ["Kromatofor", "Nöron"], a: "Yakıcı hücrelerin içinde kıvrılmış minik zıpkınlar bulunur. Dokunulunca zıpkın fırlar ve zehri karşı tarafa enjekte eder." },
  { id: "p06-119", k: "Doğa", s: "\"Ölümsüz denizanası\" olarak bilinen türün olağanüstü yeteneği nedir?", d: "Gençlik evresine geri dönebilmesi", y: ["Hiç beslenmeden yaşaması", "Kopan kafasını yenilemesi"], a: "Turritopsis dohrnii stres ya da yaralanma durumunda yeniden polip evresine dönebilir. Yine de avlanma ve hastalıkla ölebilir." },
  { id: "p06-120", k: "Doğa", s: "Avustralya ve Güneydoğu Asya sularında bulunan, çok tehlikeli zehirli denizanası grubu hangisidir?", d: "Kutu denizanaları", y: ["Ay denizanaları", "Taraklılar"], a: "Kutu denizanaları küp biçimli gövdeleriyle tanınır. Bazı türlerin zehri insan için ölümcül olabilir." },
  { id: "p06-121", k: "Doğa", s: "Portekiz savaş gemisi denilen canlının tuhaf yanı nedir?", d: "Birlikte yaşayan bir hayvan kolonisi olması", y: ["Bir balık türü olması", "Bir bitki olması"], a: "Denizanasına benzeyen Portekiz savaş gemisi aslında birbirine bağlı pek çok küçük canlıdan oluşur. Her biri yüzme, avlanma ya da sindirim gibi bir görev üstlenir." },
  { id: "p06-122", k: "Doğa", s: "Denizanası, mercan ve deniz şakayığı hangi ortak hayvan grubundadır?", d: "Knidliler (sölenterler)", y: ["Süngerler", "Derisidikenliler"], a: "Bu canlıların hepsinde yakıcı hücreler ve ağzın çevresinde dokunaçlar bulunur." },
  { id: "p06-123", k: "Doğa", s: "Mercanlar hangi canlı grubuna aittir?", d: "Hayvanlar", y: ["Bitkiler", "Mantarlar"], a: "Mercan resifleri polip denilen küçük hayvanların oluşturduğu kolonilerdir. Her polip dokunaçlarıyla minik besinleri yakalar." },
  { id: "p06-124", k: "Doğa", s: "Mercan poliplerinin dokularında yaşayıp onlara besin sağlayan canlılar hangileridir?", d: "Fotosentez yapan algler", y: ["Parazit solucanlar", "Küçük yengeçler"], a: "Zooksantel denen bu algler güneş ışığıyla besin üretip mercana verir. Mercanlara renk veren de büyük ölçüde onlardır." },
  { id: "p06-125", k: "Doğa", s: "Mercan ağarmasının başlıca nedeni nedir?", d: "Deniz suyunun aşırı ısınması", y: ["Ayın etkisi", "Suyun fazla tatlı olması"], a: "Su çok ısınınca mercanlar dokularındaki algleri dışarı atar ve bembeyaz kalır. Sular uzun süre serinlemezse mercanlar ölebilir." },
  { id: "p06-126", k: "Doğa", s: "Dünyanın en büyük mercan resifi sistemi hangisidir?", d: "Büyük Set Resifi", y: ["Kızıldeniz resifleri", "Maldiv resifleri"], a: "Büyük Set Resifi 2.000 kilometreyi aşan uzunluğuyla canlıların yaptığı en büyük yapıdır." },
  { id: "p06-127", k: "Doğa", s: "Büyük Set Resifi hangi ülkenin kıyısındadır?", d: "Avustralya", y: ["Endonezya", "Brezilya"], a: "Büyük Set Resifi Avustralya'nın kuzeydoğu kıyısı boyunca uzanır ve UNESCO Dünya Mirası listesindedir." },
  { id: "p06-128", k: "Doğa", s: "Mercan resiflerinin sert iskeleti hangi maddeden oluşur?", d: "Kalsiyum karbonat", y: ["Silika", "Kitin"], a: "Mercan polipleri sudan aldıkları maddelerle kalsiyum karbonattan iskelet yapar. Bu iskeletler yüzyıllar boyunca üst üste birikerek resifi oluşturur." },
  { id: "p06-129", k: "Doğa", s: "Süngerler hangi canlı grubuna aittir?", d: "Hayvanlar", y: ["Bitkiler", "Mantarlar"], a: "Süngerler gerçek doku ve organları olmayan en basit hayvanlardandır. Bir yere yapışık yaşarlar." },
  { id: "p06-130", k: "Doğa", s: "Deniz süngerleri nasıl beslenir?", d: "Gözeneklerinden su süzerek", y: ["Dokunaçlarıyla avlanarak", "Fotosentez yaparak"], a: "Süngerin vücudu küçük deliklerle doludur. İçinden geçen sudaki bakteri ve minik besin parçalarını süzerek yakalar." },
  { id: "p06-131", k: "Doğa", s: "Doğal banyo süngerleri aslında nedir?", d: "Bir hayvanın kurutulmuş iskeleti", y: ["Bir bitkinin kökü", "Kurutulmuş deniz yosunu"], a: "Doğal süngerler, deniz süngerlerinin canlı kısmı temizlendikten sonra kalan yumuşak iskeletidir. Bugün çoğu banyo süngeri yapaydır." },
  { id: "p06-132", k: "Doğa", s: "Deniz yıldızlarının çoğunda kaç kol bulunur?", d: "5", y: ["4", "8"], a: "Deniz yıldızlarının çoğunda beş kol vardır. Bazı türlerde bu sayı 20'yi, hatta 40'ı aşabilir." },
  { id: "p06-133", k: "Doğa", s: "Bir deniz yıldızı kolunu kaybederse ne olur?", d: "Yerine yenisini çıkarabilir", y: ["Hemen ölür", "Bir daha hareket edemez"], a: "Deniz yıldızları kopan kollarını aylar içinde yenileyebilir. Bazı türlerde kopan bir koldan bütün bir deniz yıldızı bile oluşabilir." },
  { id: "p06-134", k: "Doğa", s: "Deniz yıldızı bir midyeyi nasıl yer?", d: "Midesini dışarı çıkararak", y: ["Kabuğunu dişleriyle kırarak", "Bütün olarak yutarak"], a: "Deniz yıldızı midyenin kabuğunu kollarıyla biraz aralar. Sonra midesini ağzından dışarı çıkarıp aralıktan sokar ve midyeyi orada sindirir." },
  { id: "p06-135", k: "Doğa", s: "Deniz yıldızları hareket etmek için ne kullanır?", d: "Tüp ayaklar", y: ["Yüzgeçler", "Kanatçıklar"], a: "Kolların altında yüzlerce küçük tüp ayak bulunur. Su basıncıyla çalışan bu ayaklar yüzeye tutunup deniz yıldızını yavaşça ilerletir." },
  { id: "p06-136", k: "Doğa", s: "Deniz yıldızı hangi hayvan grubundadır?", d: "Derisidikenliler", y: ["Balıklar", "Yumuşakçalar"], a: "Deniz yıldızı adında \"yıldız\" geçse de balık değildir. Deniz kestanesi ve deniz hıyarıyla aynı gruptadır." },
  { id: "p06-137", k: "Doğa", s: "Deniz yıldızlarının basit gözleri nerede bulunur?", d: "Kol uçlarında", y: ["Gövdenin ortasında", "Tüp ayaklarının dibinde"], a: "Birçok deniz yıldızının her kolunun ucunda ışığa duyarlı basit bir göz vardır. Bunlar keskin görüntü vermez ama yön bulmaya yardım eder." },
  { id: "p06-138", k: "Doğa", s: "Japon mutfağında \"uni\" adıyla yenen deniz ürünü hangi hayvandan gelir?", d: "Deniz kestanesi", y: ["Ahtapot", "İstiridye"], a: "Uni, deniz kestanesinin içindeki turuncu renkli üreme organlarıdır. Dikenli kabuk açılarak çıkarılır." },
  { id: "p06-139", k: "Doğa", s: "Deniz kestanesinin beş dişli ağız yapısına ne ad verilir?", d: "Aristoteles'in feneri", y: ["Neptün'ün tarağı", "Arşimet'in burgusu"], a: "Bu yapıyı ilk kez Aristoteles tarif ettiği için onun adı verilmiştir. Beş sert diş kayalardaki algleri kazımaya yarar." },
  { id: "p06-140", k: "Doğa", s: "Deniz hıyarları tehlike anında ne yapabilir?", d: "İç organlarının bir kısmını dışarı atar", y: ["Elektrik akımı verir", "Su yüzüne fırlar"], a: "Bazı deniz hıyarları iç organlarını ya da yapışkan iplikleri dışarı fışkırtarak avcının dikkatini dağıtır. Kaybettikleri organları sonra yeniden oluşturabilirler." },
  { id: "p06-141", k: "Doğa", s: "Deniz hıyarları genellikle neyle beslenir?", d: "Dipteki tortu ve organik artıklar", y: ["Küçük balıklar", "Mercan polipleri"], a: "Deniz hıyarları deniz dibindeki kumu ve çamuru yutar, içindeki organik maddeleri sindirir. Böylece deniz tabanını temizlemiş olurlar." },
  { id: "p06-142", k: "Doğa", s: "Yengeçler genellikle hangi yöne yürür?", d: "Yana doğru", y: ["Yalnız ileri", "Yalnız geri"], a: "Yengeçlerin bacak eklemleri yana doğru bükülür. Bu yüzden yana yürümek onlar için en hızlı ve kolay yoldur." },
  { id: "p06-143", k: "Doğa", s: "Yengeç ve karidesin sert dış iskeleti esas olarak hangi maddeden yapılmıştır?", d: "Kitin", y: ["Keratin", "Selüloz"], a: "Kitin sağlam bir şeker zinciridir. Kabuklularda kalsiyum tuzlarıyla sertleşerek zırh gibi bir dış iskelet oluşturur." },
  { id: "p06-144", k: "Doğa", s: "Yengeç ve ıstakozlar büyümek için ne yapar?", d: "Eski kabuklarını atar", y: ["Kabuklarını esnetir", "Kabuklarına parça ekler"], a: "Sert kabuk büyümez. Hayvan eski kabuğundan sıyrılır, yeni yumuşak kabuğu sertleşmeden önce su alarak irileşir." },
  { id: "p06-145", k: "Doğa", s: "Keşiş yengeci yumuşak karnını korumak için ne kullanır?", d: "Boş salyangoz kabuklarını", y: ["Kendi ördüğü ağı", "Deniz yosununu"], a: "Keşiş yengecinin karnı yumuşaktır. Boş bir salyangoz kabuğuna yerleşir, büyüdükçe daha büyük bir kabuğa taşınır." },
  { id: "p06-146", k: "Doğa", s: "Karada yaşayan en büyük eklembacaklı hangisidir?", d: "Hindistan cevizi yengeci", y: ["Goliath kuşyiyen örümceği", "İmparator akrebi"], a: "Hindistan cevizi yengeci Hint ve Pasifik okyanuslarındaki adalarda yaşar. Güçlü kıskaçlarıyla hindistan cevizini bile kırabilir." },
  { id: "p06-147", k: "Doğa", s: "Bacak açıklığı en büyük olan eklembacaklı hangisidir?", d: "Japon örümcek yengeci", y: ["Avrupa ıstakozu", "Kral yengeç"], a: "Japon örümcek yengecinin bacakları uçtan uca 3 metreyi aşabilir. Japonya çevresindeki derin sularda yaşar." },
  { id: "p06-148", k: "Doğa", s: "Istakoz pişirilince neden kırmızıya döner?", d: "Kabuktaki pigment proteinden ayrılır", y: ["Kanı kabuğuna sızar", "Kabuğu yanıp kararır"], a: "Canlı ıstakozun kabuğundaki kırmızı astaksantin pigmenti proteinlere bağlı olduğu için koyu görünür. Isı bu bağı çözünce kırmızı renk ortaya çıkar." },
  { id: "p06-149", k: "Doğa", s: "Mantis karidesi (peygamberdevesi karidesi) neyle ünlüdür?", d: "Çok güçlü ve hızlı vuruşuyla", y: ["Işık saçmasıyla", "Karada yaşamasıyla"], a: "Mantis karidesi ön uzantılarını çok büyük bir hızla fırlatır. Bu vuruşla salyangoz kabuklarını kırabilir, akvaryum camını bile çatlatabilir." },
  { id: "p06-150", k: "Doğa", s: "Tabanca karidesi avını nasıl sersemletir?", d: "Kıskacıyla patlayan bir kabarcık oluşturarak", y: ["Zehirli diken batırarak", "Elektrik vererek"], a: "Tabanca karidesi kıskacını çok hızlı kapatınca bir hava kabarcığı oluşup patlar. Bu patlama yüksek bir ses ve şok dalgası yaratır." },
  { id: "p06-151", k: "Doğa", s: "Antarktika'da balinaların ve penguenlerin temel besinlerinden olan küçük kabuklu hangisidir?", d: "Kril", y: ["Deniz salyangozu", "Midye"], a: "Kriller karides benzeri küçük kabuklulardır ve dev sürüler oluşturur. Antarktika besin zincirinin temel taşlarındandır." },
  { id: "p06-152", k: "Doğa", s: "At nalı yengecinin mavi kanı tıpta ne için kullanılır?", d: "İlaçlarda bakteri kalıntısı aramak", y: ["Kan nakli yapmak", "Aşı üretmek"], a: "At nalı yengecinin kanındaki bir madde bakteri toksinlerine karşı pıhtılaşır. Bu özellik enjeksiyonluk ilaç ve tıbbi aletlerin temizliğini test etmede kullanılır." },
  { id: "p06-153", k: "Doğa", s: "At nalı yengeci hangi hayvanlara daha yakın akrabadır?", d: "Örümcek ve akreplere", y: ["Yengeç ve karideslere", "Salyangozlara"], a: "Adı yengeç olsa da at nalı yengeci örümceğimsilere daha yakındır. Yüz milyonlarca yıldır pek değişmediği için \"yaşayan fosil\" sayılır." },
  { id: "p06-154", k: "Doğa", s: "Midyeler nasıl beslenir?", d: "Suyu süzerek", y: ["Küçük balıkları avlayarak", "Kayaları kemirerek"], a: "Midyeler solungaçlarından su geçirir ve içindeki plankton ile organik parçacıkları süzer. Bu sırada suyu da temizlemiş olurlar." },
  { id: "p06-155", k: "Doğa", s: "Midyeler kayalara neyle tutunur?", d: "Salgıladıkları güçlü ipliklerle", y: ["Vantuzlu ayaklarla", "Kökleriyle"], a: "Midyeler bisus adı verilen sağlam iplikler salgılar. Bu iplikler dalgalara rağmen onları kayalara sıkıca bağlar." },
  { id: "p06-156", k: "Doğa", s: "İstiridyede inci nasıl oluşur?", d: "Yabancı cismin sedefle kaplanmasıyla", y: ["Kumun ısıyla erimesiyle", "Yumurtanın sertleşmesiyle"], a: "Kabuğun içine bir parazit ya da yabancı parçacık girince istiridye onu kat kat sedefle kaplar. Yıllar içinde bu katmanlar inciyi oluşturur." },
  { id: "p06-157", k: "Doğa", s: "Yaşayan en büyük çift kabuklu yumuşakça hangisidir?", d: "Dev midye (Tridacna)", y: ["Akdeniz midyesi", "Kum midyesi"], a: "Dev midyeler mercan resiflerinde yaşar ve 200 kilogramı aşabilir. Dokularındaki algler fotosentezle onlara besin sağlar." },
  { id: "p06-158", k: "Doğa", s: "Koni salyangozları avlarını nasıl yakalar?", d: "Zehirli zıpkın benzeri dişle", y: ["Ağ örerek", "Mürekkep püskürterek"], a: "Koni salyangozu zıpkın gibi bir dişi avına saplayıp zehir verir. Bazı türlerin zehri insan için tehlikelidir." },
  { id: "p06-159", k: "Doğa", s: "Bazı renkli deniz sümüklüleri (nudibranşlar) yedikleri denizanalarının yakıcı hücrelerini ne yapar?", d: "Kendi savunmalarında kullanır", y: ["Kabuk yapımında kullanır", "Hemen dışarı atar"], a: "Bazı nudibranşlar yakıcı hücreleri patlatmadan sindirim sistemlerinden sırtlarındaki çıkıntılara taşır. Bu hücreler onlara saldıranı yakar." },
  { id: "p06-160", k: "Doğa", s: "Deniz şakayığı avını nasıl yakalar?", d: "Yakıcı dokunaçlarıyla", y: ["Ağzındaki dişlerle", "Su emerek"], a: "Deniz şakayığı bir kayaya yapışık yaşar. Dokunaçlarına değen küçük canlıları yakıcı hücreleriyle felç edip ağzına götürür." },
  { id: "p06-161", k: "Doğa", s: "Ahtapotun ağzında bulunan sert yapı neye benzer?", d: "Papağan gagasına", y: ["Köpek dişlerine", "Kaplumbağa kabuğuna"], a: "Ahtapotun kolların ortasındaki ağzında sert bir gaga bulunur. Bununla yengeç ve midye kabuklarını kırabilir." },
  { id: "p06-162", k: "Doğa", s: "Kalamarlar hızla kaçarken hangi yöntemi kullanır?", d: "Su püskürterek jet itkisi", y: ["Kuyruk yüzgeciyle kürek çekme", "Kumda sürünme"], a: "Kalamar vücut boşluğuna aldığı suyu bir huniden güçlü bir şekilde dışarı püskürtür. Bu jet onu ters yöne hızla iter." },
  { id: "p06-163", k: "Doğa", s: "Ahtapotlar vantuzlarıyla dokunmanın yanında ne yapabilir?", d: "Tat alabilir", y: ["Ses duyabilir", "Işık saçabilir"], a: "Ahtapot vantuzlarında kimyasal alıcılar bulunur. Kollarıyla dokunduğu nesnenin tadını da algılayabilir." },
  { id: "p06-164", k: "Doğa", s: "Endonezya'da gözlenen bazı ahtapotlar hindistan cevizi kabuklarını ne için kullanır?", d: "Taşınabilir sığınak olarak", y: ["Yemek kabı olarak", "Yumurtalarını gömmek için"], a: "Bu ahtapotlar kabuk yarılarını yanlarında taşır, tehlikede içine saklanır. Bu davranış omurgasızlarda alet kullanımı örneği sayılır." },
  { id: "p06-165", k: "Doğa", s: "Taklitçi ahtapotu ilginç kılan özellik nedir?", d: "Başka hayvanları taklit edebilmesi", y: ["Karada yürüyebilmesi", "Kabuk taşıması"], a: "Taklitçi ahtapot kollarını ve rengini ayarlayarak aslan balığı, deniz yılanı ya da yassı balık gibi tehlikeli hayvanlara benzer." },
  { id: "p06-166", k: "Doğa", s: "Su ayıları (tardigradlar) neyle ünlüdür?", d: "Aşırı koşullara dayanmalarıyla", y: ["Çok büyük olmalarıyla", "Çok hızlı koşmalarıyla"], a: "Milimetreden küçük su ayıları kurumaya, dondurucu soğuğa ve yüksek radyasyona dayanabilir. Deneylerde uzay boşluğunda bile hayatta kalmışlardır." },
  { id: "p06-167", k: "Doğa", s: "Su ayıları ortam kuruyunca ne yapar?", d: "Kuruyup bir tür askıya alınmış hale geçer", y: ["Hemen ölür", "Kabuk örüp uyur"], a: "Su ayısı suyunu kaybedip küçük bir fıçı gibi büzülür ve yaşamsal işlevlerini neredeyse durdurur. Su bulunca yeniden canlanır." },
  { id: "p06-168", k: "Doğa", s: "Kayalara yapışık yaşayan ve midyeye benzeyen balanuslar aslında hangi gruptadır?", d: "Kabuklular", y: ["Yumuşakçalar", "Süngerler"], a: "Balanuslar yengeç ve karidesin akrabasıdır. Larvayken yüzer, sonra başlarıyla bir yüzeye yapışıp ayaklarıyla sudaki besinleri toplar." },
  { id: "p06-169", k: "Doğa", s: "Okyanus dibindeki sıcak su bacalarında yaşayan dev tüp solucanları nasıl beslenir?", d: "İçlerindeki bakteriler sayesinde", y: ["Küçük balıkları avlayarak", "Güneş ışığıyla"], a: "Dev tüp solucanlarının yetişkinlerinde ağız ve bağırsak yoktur. İçlerinde yaşayan bakteriler bacadan çıkan kimyasallardan besin üretir." },
  { id: "p06-170", k: "Doğa", s: "Güneş ışığının ulaşmadığı hidrotermal bacalarda besin zincirinin temelini ne oluşturur?", d: "Kimyasallardan besin üreten bakteriler", y: ["Deniz yosunları", "Batan ağaç gövdeleri"], a: "Bu bakteriler kükürtlü bileşiklerdeki enerjiyi kullanarak besin üretir. Buna kemosentez denir." },
  { id: "p06-171", k: "Doğa", s: "Bilinen en büyük ahtapot türü hangisidir?", d: "Pasifik dev ahtapotu", y: ["Mavi halkalı ahtapot", "Taklitçi ahtapot"], a: "Pasifik dev ahtapotu Kuzey Pasifik'in soğuk sularında yaşar. Kol açıklığı birkaç metreyi bulabilir." },
  { id: "p06-172", k: "Doğa", s: "Bilimde çok kullanılan yeşil floresan protein (GFP) ilk kez hangi canlıda bulundu?", d: "Bir denizanasında", y: ["Bir ateşböceğinde", "Bir mantarda"], a: "GFP, Aequorea victoria adlı denizanasından elde edildi. Hücrelerdeki proteinleri izlemeyi sağlayan bu buluş 2008'de Nobel Kimya Ödülü'ne konu oldu." },
  { id: "p06-173", k: "Doğa", s: "Denizanalarının yaşamındaki iki temel vücut biçimi hangileridir?", d: "Polip ve medüz", y: ["Larva ve pupa", "Tırtıl ve koza"], a: "Polip bir yere yapışık, borumsu bir evredir. Medüz ise hepimizin tanıdığı şemsiye biçimli, yüzen denizanasıdır." },
  { id: "p06-174", k: "Doğa", s: "Taraklılar (ktenoforlar) suda nasıl ilerler?", d: "Kirpik sıralarını çırparak", y: ["Su püskürterek", "Kuyruk sallayarak"], a: "Taraklıların vücudunda tarak gibi dizilmiş kirpik sıraları bulunur. Bu kirpikler ışığı kırarak gökkuşağı renklerinde parlıyormuş gibi görünür." },
  { id: "p06-175", k: "Doğa", s: "1980'lerde Karadeniz'e gemilerle taşınıp hamsi stoklarını etkileyen istilacı canlı hangisidir?", d: "Bir taraklı türü", y: ["Aslan balığı", "Balon balığı"], a: "Mnemiopsis leidyi gemilerin balast suyuyla Karadeniz'e geldi. Hamsi yumurtaları ve plankton ile beslenerek çok çoğaldı, balıkçılığı ağır etkiledi." },
  { id: "p06-176", k: "Doğa", s: "Antik çağda değerli \"Tyros moru\" boyası hangi hayvandan elde edilirdi?", d: "Bir deniz salyangozundan", y: ["Bir denizanasından", "Bir ahtapottan"], a: "Fenikeliler bu boyayı murex adlı deniz salyangozlarının salgısından üretirdi. Az boya için çok salyangoz gerektiğinden mor renk zenginliğin simgesiydi." },
  { id: "p06-177", k: "Doğa", s: "Birçok yengecin gözleri nerede bulunur?", d: "Hareketli saplar üzerinde", y: ["Kıskaçlarının ucunda", "Kabuğun altında"], a: "Sap üzerindeki gözler yengecin etrafı geniş açıyla görmesini sağlar. Tehlikede gözlerini kabuktaki oyuklara indirebilir." },
  { id: "p06-178", k: "Doğa", s: "Kemancı yengecinin erkeğini tanımayı kolaylaştıran özellik nedir?", d: "Bir kıskacının çok büyük olması", y: ["Sırtındaki uzun diken", "Mavi renkli bacakları"], a: "Erkek kemancı yengecinin bir kıskacı vücudu kadar büyüyebilir. Bunu sallayarak dişileri çeker ve rakiplerini uzak tutar." },
  { id: "p06-179", k: "Doğa", s: "Mürekkep balığının göz bebeği nasıl bir şekle sahiptir?", d: "W harfine benzer", y: ["Tam yuvarlak", "Kare"], a: "Mürekkep balığının dalgalı W biçimli göz bebeği, farklı yönlerden gelen ışığı dengelemeye yardım eder." },
  { id: "p06-180", k: "Doğa", s: "Istakoz, yengeç ve karidesin dahil olduğu \"onayaklılar\" adı nereden gelir?", d: "On bacakları olmasından", y: ["On kıskaçları olmasından", "On kez kabuk değiştirmelerinden"], a: "Onayaklıların beş çift bacağı vardır. Istakoz ve yengeçlerde ilk çift büyüyüp kıskaca dönüşmüştür." },
  { id: "p06-181", k: "Doğa", s: "Karides hangi hayvan grubundadır?", d: "Kabuklular", y: ["Yumuşakçalar", "Balıklar"], a: "Karides yengeç ve ıstakoz gibi bir kabukludur. Kabuklular da böcek ve örümceklerle birlikte eklembacaklılar şubesindedir." },
  { id: "p06-182", k: "Doğa", s: "Denizde akıntıyla sürüklenen minik canlıların genel adı nedir?", d: "Plankton", y: ["Nekton", "Mercan"], a: "Plankton yüzme gücü akıntıyı yenmeye yetmeyen küçük bitki ve hayvanlardır. Okyanus besin zincirinin temelini oluştururlar." },
  { id: "p06-183", k: "Doğa", s: "Midye, istiridye ve salyangozun ortak grubu hangisidir?", d: "Yumuşakçalar", y: ["Kabuklular", "Derisidikenliler"], a: "Yumuşakçaların çoğunun yumuşak vücudunu koruyan bir kabuğu vardır. Ahtapotta bu kabuk tamamen kaybolmuştur." },
  { id: "p06-184", k: "Doğa", s: "Çift kabuklu deniz canlılarına örnek hangisidir?", d: "İstiridye", y: ["Ahtapot", "Deniz salyangozu"], a: "İstiridye, midye ve tarak gibi çift kabuklular, vücudunu menteşe gibi açılıp kapanan iki kabukla korur." },
  { id: "p06-185", k: "Doğa", s: "Deniz tarağı (Pecten) diğer çift kabukluların çoğundan farklı olarak ne yapabilir?", d: "Kabuklarını çırparak yüzebilir", y: ["Karada yürüyebilir", "Işık saçabilir"], a: "Deniz tarağı kabuklarını hızla açıp kapatarak su püskürtür ve sıçrar gibi yüzer. Kabuğun kenarında da çok sayıda küçük gözü vardır." },
  { id: "p06-186", k: "Doğa", s: "Deniz kestanesinin vücudunu ne kaplar?", d: "Hareketli dikenler", y: ["Pullar", "Tüyler"], a: "Deniz kestanesinin dikenleri hem korunmaya hem de hareket etmeye yarar. Dikenlerin arasından tüp ayaklar da uzanır." },
  { id: "p06-187", k: "Doğa", s: "Mercan resifleri dünyanın hangi tür denizlerinde en iyi gelişir?", d: "Sıcak, sığ ve berrak denizlerde", y: ["Soğuk ve bulanık sularda", "Kutup buzlarının altında"], a: "Resif yapan mercanların algleri ışığa ihtiyaç duyar. Bu yüzden resifler çoğunlukla tropik bölgelerin sığ ve berrak sularında bulunur." },
  { id: "p06-188", k: "Doğa", s: "Ahtapotlar çoğunlukla ne kadar yaşar?", d: "Birkaç yıl ya da daha az", y: ["Elli yıldan fazla", "Yaklaşık yüz yıl"], a: "Ahtapotlar zeki ama kısa ömürlü hayvanlardır. Pek çok tür bir iki yıl yaşar; büyük türler biraz daha uzun yaşayabilir." },
  { id: "p06-189", k: "Doğa", s: "Bu deniz canlılarından hangisi kabuklular grubundadır?", d: "Istakoz", y: ["Kalamar", "İstiridye"], a: "Istakozun eklemli bacakları ve kitinden dış iskeleti vardır, bu yüzden kabukludur. Kalamar ve istiridye yumuşakçadır." },
  { id: "p06-190", k: "Doğa", s: "Ay denizanası adını neyinden alır?", d: "Yarı saydam yuvarlak şemsiyesinden", y: ["Yalnız dolunayda çıkmasından", "Gece ışık saçmasından"], a: "Ay denizanasının saydam, yuvarlak şemsiyesi dolunaya benzer. Ortasındaki dört halka da üreme organlarıdır." },
  { id: "p06-191", k: "Doğa", s: "Bazı deniz salyangozlarının kabuk ağzını kapatan sert kapağa ne denir?", d: "Operkulum", y: ["Sifon", "Manto"], a: "Operkulum, salyangoz kabuğa çekildiğinde girişi kapı gibi kapatır. Bu sayede kurumaya ve avcılara karşı korunur." },
  { id: "p06-192", k: "Doğa", s: "Deniz yıldızları kan yerine besin ve gaz taşımada büyük ölçüde neyi kullanır?", d: "Vücuttaki deniz suyunu", y: ["Kırmızı kanı", "Havayı"], a: "Deniz yıldızlarında gerçek bir kan dolaşımı yoktur. Vücut boşluklarındaki ve su damar sistemindeki deniz suyu taşıma işini büyük ölçüde üstlenir." },
  { id: "p06-193", k: "Doğa", s: "Ergin böceklerin kaç bacağı vardır?", d: "6", y: ["8", "10"], a: "Böceklerin üç çift, yani altı bacağı vardır. Bacakların hepsi vücudun orta bölümü olan göğse bağlıdır." },
  { id: "p06-194", k: "Doğa", s: "Örümceklerin kaç bacağı vardır?", d: "8", y: ["6", "10"], a: "Örümceklerin dört çift bacağı vardır. Bu yüzden böcek değil, örümceğimsiler grubundandırlar." },
  { id: "p06-195", k: "Doğa", s: "Örümcekler hangi hayvan grubuna aittir?", d: "Örümceğimsiler", y: ["Böcekler", "Kabuklular"], a: "Örümcekler sık sanıldığı gibi böcek değildir. Akrep, kene ve akarlarla birlikte örümceğimsiler grubundadır." },
  { id: "p06-196", k: "Doğa", s: "Bir böceğin vücudu kaç ana bölümden oluşur?", d: "3", y: ["2", "4"], a: "Böceklerin vücudu baş, göğüs ve karın olmak üzere üç bölümdür. Anten ve gözler başta, bacak ve kanatlar göğüstedir." },
  { id: "p06-197", k: "Doğa", s: "Bir örümceğin vücudu kaç ana bölümden oluşur?", d: "2", y: ["3", "4"], a: "Örümceklerde baş ile göğüs kaynaşmıştır. Vücut bu baş-göğüs ile karın olmak üzere iki bölümdür." },
  { id: "p06-198", k: "Doğa", s: "Böcekler nefes almak için hangi yapıları kullanır?", d: "Soluk boruları (trakeler)", y: ["Akciğerler", "Solungaçlar"], a: "Böceklerin vücudunda ince borulardan oluşan bir ağ vardır. Hava yanlardaki deliklerden girip bu borularla doğrudan dokulara ulaşır." },
  { id: "p06-199", k: "Doğa", s: "Böceklerin dış iskeleti esas olarak hangi maddeden oluşur?", d: "Kitin", y: ["Kalsiyum karbonat", "Keratin"], a: "Kitin sağlam ve hafif bir maddedir. Böceğin dış iskeleti hem zırh görevi görür hem de su kaybını azaltır." },
  { id: "p06-200", k: "Doğa", s: "Bal arıları besin kaynağının yerini kovandaki arkadaşlarına nasıl bildirir?", d: "Özel bir dansla", y: ["Yüksek sesle vızıldayarak", "Renk değiştirerek"], a: "Kaynak uzaktaysa arı sekiz çizen bir sallanma dansı yapar. Dansın yönü güneşe göre yönü, süresi de uzaklığı anlatır." },
  { id: "p06-201", k: "Doğa", s: "Bir bal arısı kolonisinde yumurtlayan tek dişi hangisidir?", d: "Kraliçe arı", y: ["İşçi arı", "Erkek arı"], a: "Kraliçe arı yazın günde yüzlerce, hatta binlerce yumurta bırakabilir. İşçi arılar da dişidir ama normalde yumurtlamaz." },
  { id: "p06-202", k: "Doğa", s: "Bal arısı kolonisindeki işçi arılar hangi cinsiyettedir?", d: "Dişi", y: ["Erkek", "Cinsiyetsiz"], a: "Kovandaki tüm işleri, yani petek örmeyi, bal yapmayı ve kovanı korumayı dişi işçiler yapar. Erkek arıların temel görevi kraliçeyle çiftleşmektir." },
  { id: "p06-203", k: "Doğa", s: "Erkek bal arılarının iğnesi var mıdır?", d: "Yoktur", y: ["Vardır ve zehirlidir", "Yalnız kışın vardır"], a: "Arı iğnesi aslında değişime uğramış bir yumurtlama borusudur. Bu yüzden yalnız dişilerde bulunur, erkek arılar sokamaz." },
  { id: "p06-204", k: "Doğa", s: "Bal arısı bir insanı soktuktan sonra çoğu zaman neden ölür?", d: "Tırtıklı iğnesi deride kalıp kopar", y: ["Zehri kendine de bulaşır", "Kalbi durur"], a: "Bal arısının iğnesi tırtıklıdır ve insan derisine takılır. Arı uzaklaşırken iğne, zehir kesesiyle birlikte kopar ve arı ölür." },
  { id: "p06-205", k: "Doğa", s: "Bal arısı larvasını kraliçe yapan temel etken nedir?", d: "Arı sütüyle beslenmesi", y: ["Daha büyük yumurtadan çıkması", "Kışın doğması"], a: "Tüm larvalar ilk günlerde arı sütü alır. Kraliçe olacak larva ise gelişimi boyunca bol arı sütüyle beslenir." },
  { id: "p06-206", k: "Doğa", s: "Bal arısı peteklerindeki gözler hangi şekildedir?", d: "Altıgen", y: ["Kare", "Üçgen"], a: "Altıgen gözler aralarında boşluk bırakmadan birleşir. Bu şekil en az balmumuyla en fazla depolama alanı sağlar." },
  { id: "p06-207", k: "Doğa", s: "Bal arıları balı esas olarak neyden üretir?", d: "Çiçek nektarından", y: ["Polenden", "Ağaç reçinesinden"], a: "Arılar nektarı toplayıp enzimlerle işler ve suyunu buharlaştırır. Polen ise daha çok protein kaynağı olarak yavrulara verilir." },
  { id: "p06-208", k: "Doğa", s: "Bal arıları insanların göremediği hangi ışığı görebilir?", d: "Morötesi ışığı", y: ["Kızılötesi ışığı", "Radyo dalgalarını"], a: "Birçok çiçeğin yapraklarında yalnız morötesi ışıkta görünen desenler vardır. Bu desenler arılara nektarın yerini gösterir." },
  { id: "p06-209", k: "Doğa", s: "Bal arıları balmumunu nasıl elde eder?", d: "Karınlarındaki bezlerden salgılar", y: ["Ağaçlardan toplar", "Çiçeklerden emer"], a: "Genç işçi arılar karınlarının altındaki bezlerden ince balmumu pulları salgılar. Bunları çiğneyip şekillendirerek petek örerler." },
  { id: "p06-210", k: "Doğa", s: "Bal arıları kovanı serinletmek için ne yapar?", d: "Kanat çırpıp hava akımı oluşturur", y: ["Kovanı terk eder", "Gölgede uyur"], a: "Sıcakta arılar kovan girişinde dizilip kanat çırparak havalandırma yapar. Getirdikleri suyun buharlaşması da kovanı serinletir." },
  { id: "p06-211", k: "Doğa", s: "Bal arıları kışın kovanda nasıl ısınır?", d: "Kümelenip kaslarını titreterek", y: ["Kış uykusuna yatarak", "Kovanı yaprakla örterek"], a: "Arılar kraliçenin çevresinde sıkı bir küme oluşturur. Uçuş kaslarını kanat çırpmadan titreterek ısı üretirler." },
  { id: "p06-212", k: "Doğa", s: "Bal arıları topladıkları poleni nerede taşır?", d: "Arka bacaklarındaki polen sepetinde", y: ["Ağızlarında", "Kanatlarının altında"], a: "İşçi arıların arka bacaklarında kıllarla çevrili bir çukur bulunur. Polen burada küçük topaklar halinde kovana taşınır." },
  { id: "p06-213", k: "Doğa", s: "Yaz aylarında çalışan bir işçi bal arısı yaklaşık ne kadar yaşar?", d: "Birkaç hafta", y: ["Birkaç yıl", "Birkaç gün"], a: "Yazın yoğun çalışan işçi arılar genellikle birkaç hafta yaşar. Kraliçe ise birkaç yıl yaşayabilir." },
  { id: "p06-214", k: "Doğa", s: "Arılar balı koyulaştırmak için nektardaki suyu nasıl azaltır?", d: "Kanat çırparak buharlaştırır", y: ["Güneşte kurutur", "Polen karıştırır"], a: "Nektar petek gözlerine konur, arılar kanat çırparak suyun buharlaşmasını hızlandırır. Bal yeterince koyulaşınca göz balmumuyla kapatılır." },
  { id: "p06-215", k: "Doğa", s: "Karıncalar birbirleriyle en çok nasıl haberleşir?", d: "Kimyasal kokularla (feromon)", y: ["Ses çıkararak", "Işık yakıp söndürerek"], a: "Karıncalar feromon denen kimyasallarla iz bırakır ve tehlikeyi duyurur. Yolda sıra halinde yürümeleri de bu kimyasal izi takip etmelerindendir." },
  { id: "p06-216", k: "Doğa", s: "Yaprak kesen karıncalar kestikleri yaprakları ne için kullanır?", d: "Mantar yetiştirmek için", y: ["Doğrudan yemek için", "Yuvayı süslemek için"], a: "Yaprak kesen karıncalar yaprakları yuvalarına taşıyıp üzerinde mantar yetiştirir. Asıl besinleri bu mantardır." },
  { id: "p06-217", k: "Doğa", s: "Ordu karıncaları neyle bilinir?", d: "Kalıcı yuva yapmayıp göç etmeleriyle", y: ["Bal üretmeleriyle", "Yalnız yaşamalarıyla"], a: "Ordu karıncaları büyük kolonilerle yürüyerek avlanır. Kalıcı yuva yerine, birbirlerine tutunarak kendi bedenlerinden geçici yuvalar kurarlar." },
  { id: "p06-218", k: "Doğa", s: "Karıncaların en yakın akrabaları hangi böceklerdir?", d: "Arılar ve eşekarıları", y: ["Termitler", "Hamamböcekleri"], a: "Karıncalar, arılar ve eşekarıları zar kanatlılar takımındadır. Termitler karıncaya benzese de hamamböceklerine daha yakındır." },
  { id: "p06-219", k: "Doğa", s: "Termitlere en yakın akraba olan böcekler hangileridir?", d: "Hamamböcekleri", y: ["Karıncalar", "Arılar"], a: "Termitlere \"beyaz karınca\" da denir ama karınca değildir. Bugün hamamböceklerinden evrimleşmiş bir grup olarak kabul edilirler." },
  { id: "p06-220", k: "Doğa", s: "Termitler odundaki selülozu nasıl sindirebilir?", d: "Bağırsaklarındaki mikroplar sayesinde", y: ["Güçlü çeneleri sayesinde", "Odunu yakarak"], a: "Termitlerin bağırsaklarında yaşayan bakteri ve tek hücreli canlılar selülozu parçalar. Termitler bu mikroplar olmadan odundan besin alamaz." },
  { id: "p06-221", k: "Doğa", s: "Tırtılın kelebeğe dönüştüğü, koza içindeki evreye ne denir?", d: "Pupa", y: ["Larva", "Nimf"], a: "Pupa evresinde tırtılın vücudu büyük ölçüde yeniden düzenlenir. Sonunda kanatlı ergin kelebek pupadan çıkar." },
  { id: "p06-222", k: "Doğa", s: "Yumurta, larva, pupa ve ergin evrelerinden geçen gelişime ne ad verilir?", d: "Tam başkalaşım", y: ["Eksik başkalaşım", "Tomurcuklanma"], a: "Kelebek, arı, sinek ve kınkanatlılar tam başkalaşım geçirir. Bu böceklerde larva ile ergin çok farklı görünür." },
  { id: "p06-223", k: "Doğa", s: "Yavrusu erginine benzeyen, pupa evresi olmayan böcek hangisidir?", d: "Çekirge", y: ["Kelebek", "Bal arısı"], a: "Çekirge yavruları kanatsız küçük çekirgeler gibidir. Birkaç kez deri değiştirerek büyür ve kanatlanır; buna eksik başkalaşım denir." },
  { id: "p06-224", k: "Doğa", s: "Kelebekler bir yaprağın tadını nasıl algılar?", d: "Ayaklarıyla", y: ["Kanatlarıyla", "Antenlerinin ucuyla"], a: "Kelebeklerin ayaklarında tat alıcıları bulunur. Dişiler yumurtlamadan önce yaprağa konarak tırtılları için uygun bitkiyi bu yolla seçer." },
  { id: "p06-225", k: "Doğa", s: "Kelebekler çiçek nektarını neyle emer?", d: "Kıvrık bir hortumla", y: ["Dişleriyle", "Ayaklarıyla"], a: "Kelebeğin ağzı pipet gibi uzun bir hortumdur. Kullanmadığı zaman bu hortumu yay gibi kıvırıp başının altında tutar." },
  { id: "p06-226", k: "Doğa", s: "Kelebek kanatlarındaki renkler neyden kaynaklanır?", d: "Kiremit gibi dizilmiş minik pullardan", y: ["Kanattaki kandan", "Yuttuğu çiçek tozundan"], a: "Kelebek kanatları binlerce minik pulla kaplıdır. Renkler pullardaki pigmentlerden ya da ışığı kıran yapılarından gelir." },
  { id: "p06-227", k: "Doğa", s: "Kral (monark) kelebekleri kışı geçirmek için Kuzey Amerika'dan nereye göç eder?", d: "Meksika'ya", y: ["Grönland'a", "Alaska'ya"], a: "Milyonlarca kral kelebeği binlerce kilometre uçarak Meksika'daki dağ ormanlarında kışlar. Dönüş yolculuğunu birkaç kuşak birlikte tamamlar." },
  { id: "p06-228", k: "Doğa", s: "Kral kelebeklerini kuşlar için zehirli yapan nedir?", d: "Tırtılken yedikleri ipekotu bitkisi", y: ["Kanatlarındaki iğneler", "Ürettikleri zehirli gaz"], a: "Kral kelebeği tırtılları zehirli maddeler içeren ipekotu yaprakları yer. Bu maddeler vücutlarında kalır ve onları kuşlar için acı ve zehirli yapar." },
  { id: "p06-229", k: "Doğa", s: "Kelebeklerin antenleri güvelerinkinden genellikle nasıl ayrılır?", d: "Uçları topuz gibidir", y: ["Hiç anten yoktur", "Daha çok sayıdadır"], a: "Kelebek antenleri ince bir sapın ucunda topuzla biter. Güvelerin antenleri ise çoğunlukla ince ya da tüy gibidir." },
  { id: "p06-230", k: "Doğa", s: "İpek, ipek böceğinin hangi evresinde üretilir?", d: "Tırtılken koza örerken", y: ["Erginken uçarken", "Yumurtadan çıkarken"], a: "İpek böceği tırtılı ağzındaki bezlerden çıkan tek ve uzun bir iplikle koza örer. İpek bu kozaların çözülmesiyle elde edilir." },
  { id: "p06-231", k: "Doğa", s: "İpek böceği tırtılları neyle beslenir?", d: "Dut yaprağı", y: ["Asma yaprağı", "Çam iğnesi"], a: "İpek böceği tırtılları neredeyse yalnız dut yaprağı yer. Bursa'da ipekçiliğin gelişmesi de bu yüzden dut bahçeleriyle iç içedir." },
  { id: "p06-232", k: "Doğa", s: "İpek üretimi ilk olarak hangi ülkede başladı?", d: "Çin", y: ["Hindistan", "İran"], a: "İpekçilik binlerce yıl önce Çin'de başladı ve uzun süre sır olarak saklandı. İpek Yolu adını bu değerli kumaştan alır." },
  { id: "p06-233", k: "Doğa", s: "Sivrisineklerde insan ve hayvanlardan kan emen hangisidir?", d: "Yalnız dişiler", y: ["Yalnız erkekler", "Dişi ve erkekler"], a: "Erkek sivrisinekler yalnız bitki özsuyu ve nektarla beslenir. Dişiler de nektar içer ama yumurta üretmek için kana ihtiyaç duyar." },
  { id: "p06-234", k: "Doğa", s: "Dişi sivrisinekler kanı ne için kullanır?", d: "Yumurta üretmek için", y: ["Kanatlarını güçlendirmek için", "Kışı geçirmek için"], a: "Kandaki protein ve demir dişinin yumurtalarını geliştirmesi için gereklidir. Kan emmeyen dişi genellikle yeterli yumurta üretemez." },
  { id: "p06-235", k: "Doğa", s: "Sıtmayı insanlara bulaştıran sivrisinek cinsi hangisidir?", d: "Anofel (Anopheles)", y: ["Aedes", "Culex"], a: "Sıtma, yalnız Anofel cinsi dişi sivrisineklerin sokmasıyla bulaşır. Aedes cinsi ise dang ve zika gibi hastalıkları taşır." },
  { id: "p06-236", k: "Doğa", s: "Sıtma hastalığına ne tür bir canlı yol açar?", d: "Tek hücreli bir parazit", y: ["Bir virüs", "Bir mantar"], a: "Sıtmaya Plasmodium adlı tek hücreli parazitler neden olur. Sivrisinek bu parazitleri sokma sırasında insana aktarır." },
  { id: "p06-237", k: "Doğa", s: "Sivrisinekler insanları bulurken en çok neyi izler?", d: "Nefesteki karbondioksiti", y: ["Kalp seslerini", "Giysi renklerini"], a: "Sivrisinekler soluduğumuz havadaki karbondioksiti uzaktan algılar. Yaklaştıkça vücut ısısı ve ter kokusu da onlara yol gösterir." },
  { id: "p06-238", k: "Doğa", s: "Sivrisinek larvaları nerede gelişir?", d: "Durgun suda", y: ["Ağaç kabuğunda", "Kuru toprakta"], a: "Sivrisinekler yumurtalarını durgun suya bırakır. Saksı altlığı ya da eski lastikte biriken su bile larvalar için yeterlidir." },
  { id: "p06-239", k: "Doğa", s: "Ateşböcekleri ışıklarını en çok ne için kullanır?", d: "Eş bulmak için", y: ["Önlerini görmek için", "Isınmak için"], a: "Her ateşböceği türünün kendine özgü bir yanıp sönme düzeni vardır. Erkekler ve dişiler bu ışık sinyalleriyle birbirini bulur." },
  { id: "p06-240", k: "Doğa", s: "Ateşböcekleri hangi böcek takımındadır?", d: "Kınkanatlılar", y: ["Sinekler", "Kelebekler"], a: "Ateşböcekleri adına rağmen sinek değil, bir tür kınkanatlıdır. Ön kanatları sert bir kına dönüşmüştür." },
  { id: "p06-241", k: "Doğa", s: "Bilinen tür sayısı en fazla olan böcek takımı hangisidir?", d: "Kınkanatlılar", y: ["Kelebekler", "Sinekler"], a: "Uğur böceği, bok böceği ve gergedan böceği gibi kınkanatlılar böceklerin en kalabalık takımıdır. Hayvan türlerinin önemli bir kısmı bu gruptadır." },
  { id: "p06-242", k: "Doğa", s: "Uğur böcekleri bahçelerde hangi zararlıları yiyerek faydalı olur?", d: "Yaprak bitlerini", y: ["Solucanları", "Arıları"], a: "Bir uğur böceği yaşamı boyunca binlerce yaprak biti yiyebilir. Bu yüzden tarımda doğal zararlı kontrolü için kullanılır." },
  { id: "p06-243", k: "Doğa", s: "Bazı bok böcekleri gece yönlerini bulmak için neyi kullanır?", d: "Samanyolu'nun ışığını", y: ["Dünya'nın manyetik alanını", "Ağaçların gölgesini"], a: "Deneylerde bazı bok böceklerinin aysız gecelerde Samanyolu'nun parlak şeridine bakarak düz bir çizgide ilerlediği görüldü." },
  { id: "p06-244", k: "Doğa", s: "Antik Mısır'da kutsal sayılan ve skarabe adıyla bilinen böcek hangisidir?", d: "Bok böceği", y: ["Uğur böceği", "Ateşböceği"], a: "Mısırlılar gübre topunu yuvarlayan bok böceğini güneşi gökte yuvarlayan tanrıya benzetirdi. Skarabe biçimli muskalar çok yaygındı." },
  { id: "p06-245", k: "Doğa", s: "Bazı peygamberdevesi türlerinde çiftleşme sırasında ya da sonrasında ne olabilir?", d: "Dişi erkeği yiyebilir", y: ["Erkek dişiyi yiyebilir", "İkisi birlikte ölür"], a: "Bazı türlerde dişinin erkeği yediği gözlemlenmiştir. Ancak bu her çiftleşmede olmaz, doğada laboratuvardakinden daha seyrektir." },
  { id: "p06-246", k: "Doğa", s: "Peygamberdevesi dikenli ön bacaklarını ne için kullanır?", d: "Avını yakalayıp tutmak için", y: ["Toprak kazmak için", "Ses çıkarmak için"], a: "Peygamberdevesi ön bacaklarını dua eder gibi katlayarak bekler. Av yaklaşınca bu dikenli bacakları hızla açıp avını yakalar." },
  { id: "p06-247", k: "Doğa", s: "Cırcır böcekleri seslerini nasıl çıkarır?", d: "Kanatlarını birbirine sürterek", y: ["Ağızlarıyla öterek", "Bacaklarını yere vurarak"], a: "Erkek cırcır böceği bir kanadındaki törpü benzeri kenarı diğerindeki sert çıkıntıya sürter. Bu sürtünme bildiğimiz cırcır sesini çıkarır." },
  { id: "p06-248", k: "Doğa", s: "Cırcır böceklerinin kulakları nerede bulunur?", d: "Ön bacaklarında", y: ["Başlarının yanında", "Antenlerinin ucunda"], a: "Cırcır böceklerinin ön bacaklarında ince bir zar bulunur. Bu zar kulak zarı gibi titreşerek sesleri algılar." },
  { id: "p06-249", k: "Doğa", s: "Kuzey Amerika'daki periyodik ağustosböcekleri kaç yılda bir topluca toprak üstüne çıkar?", d: "13 ya da 17 yılda bir", y: ["2 ya da 3 yılda bir", "5 ya da 7 yılda bir"], a: "Bu ağustosböceklerinin yavruları 13 ya da 17 yıl toprak altında kök özsuyu emerek yaşar. Sonra milyonlarcası aynı anda yüzeye çıkar." },
  { id: "p06-250", k: "Doğa", s: "Ağustosböceklerinde yüksek sesli ötüşü hangisi yapar?", d: "Erkekler", y: ["Dişiler", "Yalnız yavrular"], a: "Erkek ağustosböceklerinin karnında zar gibi titreşen özel ses organları vardır. Bu ötüşle dişileri çağırırlar." },
  { id: "p06-251", k: "Doğa", s: "Çöl çekirgeleri çok kalabalıklaştığında ne olur?", d: "Renk ve davranış değiştirip sürü olur", y: ["Kış uykusuna yatarlar", "Birbirlerinden uzaklaşırlar"], a: "Kalabalıklaşan çöl çekirgeleri renk değiştirir ve sürü halinde hareket etmeye başlar. Bu dev sürüler ekinleri kısa sürede yok edebilir." },
  { id: "p06-252", k: "Doğa", s: "Yusufçuk larvaları nerede yaşar?", d: "Suda", y: ["Ağaç kovuklarında", "Toprak altında"], a: "Yusufçuk larvaları göl ve derelerde yaşayan avcılardır. Bazı türlerde larva evresi yıllarca sürebilir, ergin yaşamı ise çok kısadır." },
  { id: "p06-253", k: "Doğa", s: "Karbonifer döneminde yaşamış dev yusufçuk benzeri böcek hangisidir?", d: "Meganeura", y: ["Arkeopteriks", "Anomalokaris"], a: "Meganeura'nın kanat açıklığı yaklaşık 70 santimetreye ulaşıyordu. Bilinen en büyük uçan böcekler arasındadır." },
  { id: "p06-254", k: "Doğa", s: "Ev sineği katı yiyecekleri nasıl yer?", d: "Tükürükle eritip emerek", y: ["Dişleriyle çiğneyerek", "Bütün olarak yutarak"], a: "Ev sineğinin çiğneyecek dişleri yoktur. Yiyeceğin üstüne tükürük bırakıp onu sıvılaştırır, sonra sünger gibi ağzıyla emer." },
  { id: "p06-255", k: "Doğa", s: "Böceklerin binlerce küçük birimden oluşabilen gözüne ne ad verilir?", d: "Bileşik göz", y: ["Tek mercekli göz", "Kamera gözü"], a: "Bileşik göz çok sayıda küçük göz biriminden oluşur. Her birim görüntünün bir parçasını alır; bu göz hareketi algılamada çok başarılıdır." },
  { id: "p06-256", k: "Doğa", s: "Sineklerde arka kanatların dönüştüğü denge organına ne denir?", d: "Halter", y: ["Anten", "Hortum"], a: "Sineklerin yalnız bir çift uçuş kanadı vardır. Arka kanatlar küçük topuzlu çubuklara dönüşmüştür ve uçuşta jiroskop gibi denge sağlar." },
  { id: "p06-257", k: "Doğa", s: "Pirelerin vücut boylarına göre çok yükseğe sıçramasında rol oynayan elastik protein hangisidir?", d: "Resilin", y: ["Kolajen", "Keratin"], a: "Resilin yay gibi enerji depolayıp birden geri verir. Pire bacağındaki resilin, kasların tek başına sağlayamayacağı hızda bir sıçrama sağlar." },
  { id: "p06-258", k: "Doğa", s: "Orta Çağ'daki veba salgınlarında hastalığı farelerden insanlara taşıyan başlıca canlı hangisidir?", d: "Pire", y: ["Sivrisinek", "Hamamböceği"], a: "Vebaya yol açan bakteri, fareler gibi kemirgenlerde yaşayan pirelerle taşındı. Pireler hasta hayvandan insana atlayıp ısırarak hastalığı bulaştırdı." },
  { id: "p06-259", k: "Doğa", s: "Lyme hastalığını insanlara bulaştıran canlı hangisidir?", d: "Kene", y: ["Sivrisinek", "Karasinek"], a: "Lyme hastalığına yol açan bakteri bazı kene türlerinin ısırmasıyla bulaşır. Keneler böcek değil, örümceğimsidir." },
  { id: "p06-260", k: "Doğa", s: "Akrepler morötesi ışık altında nasıl görünür?", d: "Parlar", y: ["Görünmez olur", "Kapkara olur"], a: "Akrebin dış iskeletindeki bazı maddeler morötesi ışıkta mavi-yeşil parlar. Araştırmacılar gece akrep ararken bu yüzden UV lamba kullanır." },
  { id: "p06-261", k: "Doğa", s: "Dişi akrepler yeni doğan yavrularını nerede taşır?", d: "Sırtında", y: ["Ağzında", "Kıskaçlarında"], a: "Akrepler canlı doğurur. Yavrular ilk deri değiştirmelerine kadar annelerinin sırtında taşınır ve korunur." },
  { id: "p06-262", k: "Doğa", s: "Akrebin zehir iğnesi nerede bulunur?", d: "Kuyruğunun ucunda", y: ["Kıskaçlarının içinde", "Ağzının yanında"], a: "Akrebin kuyruğu karnının devamıdır ve ucunda zehir kesesiyle iğne bulunur. Kıskaçlar ise avı tutmaya yarar." },
  { id: "p06-263", k: "Doğa", s: "Örümcek ipeği temelde nasıl bir maddedir?", d: "Protein", y: ["Selüloz", "Bir tür yağ"], a: "Örümcek ipeği, vücutta sıvı halde üretilen bir proteindir. Dışarı çekilirken sağlam bir ipliğe dönüşür." },
  { id: "p06-264", k: "Doğa", s: "Örümcekler ipeği vücutlarının neresinden çıkarır?", d: "Karın ucundaki iplik memelerinden", y: ["Ağızlarından", "Bacak uçlarından"], a: "Örümceğin karnının ucunda iplik memeleri bulunur. Örümcek farklı işler için farklı türde ipek üretebilir." },
  { id: "p06-265", k: "Doğa", s: "Örümcekler avlarını çoğunlukla nasıl sindirir?", d: "Sindirim sıvısıyla dışarıda eriterek", y: ["Dişleriyle çiğneyerek", "Bütün olarak yutarak"], a: "Örümcekler avlarına sindirim sıvısı akıtır. Av dokuları sıvılaşınca örümcek bu karışımı emer." },
  { id: "p06-266", k: "Doğa", s: "Kara dul örümceğinin dişisi hangi işaretle tanınır?", d: "Karnındaki kırmızı kum saati deseni", y: ["Sırtındaki beyaz çarpı", "Mavi renkli bacakları"], a: "Parlak siyah kara dul dişisinin karnının altında kırmızı bir kum saati deseni bulunur. Isırığı tehlikeli olabilir ama örümcek saldırgan değildir." },
  { id: "p06-267", k: "Doğa", s: "Amerika'da yaşayan bazı tarantulalar tehdit edilince kendilerini nasıl korur?", d: "Kaşındırıcı kıllarını fırlatır", y: ["Zehir püskürtür", "Bacaklarını koparır"], a: "Bu tarantulalar arka bacaklarıyla karınlarındaki tahriş edici kılları düşmana savurur. Kıllar gözde ve deride yanma, kaşıntı yapar." },
  { id: "p06-268", k: "Doğa", s: "Örümceklerin çoğunda kaç göz bulunur?", d: "8", y: ["2", "4"], a: "Örümceklerin çoğu sekiz gözlüdür. Bazı türlerde altı, dört ya da daha az göz bulunur, mağara örümceklerinden bazıları ise kördür." },
  { id: "p06-269", k: "Doğa", s: "Zıplayan örümcekler hangi özellikleriyle bilinir?", d: "Çok keskin görmeleriyle", y: ["Dev ağlar örmeleriyle", "Su altında yaşamalarıyla"], a: "Zıplayan örümceklerin öndeki iri gözleri çok keskin görür. Ağ örmek yerine avlarını gözleriyle izleyip üstlerine atlarlar." },
  { id: "p06-270", k: "Doğa", s: "Su örümceği (Argyroneta) su altında nasıl nefes alır?", d: "İpekten kurduğu hava kabarcığında", y: ["Solungaçlarıyla", "Derisinden su süzerek"], a: "Su örümceği su altındaki bitkilere ipekten bir çan örer ve içini yüzeyden taşıdığı havayla doldurur. Zamanının çoğunu bu hava kabarcığında geçirir." },
  { id: "p06-271", k: "Doğa", s: "Yavru örümcekler çok uzak yerlere nasıl ulaşabilir?", d: "İpek ipliğiyle rüzgârda uçarak", y: ["Kuşların sırtına binerek", "Suda yüzerek"], a: "Balonlama denen bu davranışta örümcek ince ipek iplikleri havaya salar. Rüzgâr ve havadaki elektrik onu kilometrelerce taşıyabilir." },
  { id: "p06-272", k: "Doğa", s: "Dişi örümcekler yumurtalarını genellikle nerede saklar?", d: "İpekten bir kesede", y: ["Toprak altında çıplak olarak", "Yaprakların içinde"], a: "Dişi örümcek yumurtalarını ipekten ördüğü bir kozaya yerleştirir. Bazı türler bu keseyi yanında taşır." },
  { id: "p06-273", k: "Doğa", s: "Kurt örümcekleri avlarını nasıl yakalar?", d: "Kovalayarak ya da pusu kurarak", y: ["Büyük ağlar örerek", "Zehirli gaz salarak"], a: "Kurt örümcekleri ağ örmez, iyi gözleriyle avlarını izleyip üstüne atlar. Dişiler yavrularını bir süre sırtlarında taşır." },
  { id: "p06-274", k: "Doğa", s: "Örümcek zehri insanlar için genellikle nasıldır?", d: "Çoğu tür için zararsızdır", y: ["Her tür için ölümcüldür", "Hiçbir örümcekte zehir yoktur"], a: "Örümceklerin büyük çoğunluğu zehirlidir ama zehirleri küçük avlar içindir. Yalnız birkaç türün ısırığı insanda ciddi sorun yaratır." },
  { id: "p06-275", k: "Doğa", s: "Akreplerin en yakın akrabaları hangi gruptadır?", d: "Örümceğimsiler", y: ["Böcekler", "Kabuklular"], a: "Akrepler de örümcekler gibi sekiz bacaklıdır ve örümceğimsiler grubundadır. Önlerindeki kıskaçlar değişime uğramış ağız uzantılarıdır." },
  { id: "p06-276", k: "Doğa", s: "Çıyanlar (Chilopoda) avlarını neyle zehirler?", d: "Başlarının yanındaki zehir pençeleriyle", y: ["Kuyruklarındaki iğneyle", "Antenleriyle"], a: "Çıyanların ilk bacak çifti zehirli pençelere dönüşmüştür. Bunlarla böcek ve küçük hayvanları yakalayıp zehirler." },
  { id: "p06-277", k: "Doğa", s: "Kırkayakları (Diplopoda) çıyanlardan ayıran özellik nedir?", d: "Her halkada iki çift bacak olması", y: ["Kanatlarının olması", "Sekiz bacaklı olmaları"], a: "Kırkayakların vücut halkalarının çoğunda iki çift bacak bulunur, çıyanlarda ise bir çift. Kırkayaklar genellikle çürüyen bitkilerle beslenir." },
  { id: "p06-278", k: "Doğa", s: "Kırkayakların bacak sayısı için hangisi doğrudur?", d: "Türe göre çok değişir", y: ["Tam olarak kırktır", "Tam olarak yüzdür"], a: "Kırkayakların bacak sayısı türüne göre birkaç düzineden yüzlerceye kadar değişir. Bin bacağı aşan bir tür bile bulunmuştur." },
  { id: "p06-279", k: "Doğa", s: "Yüz milyonlarca yıl önce denizlerde yaşamış, soyu tükenmiş eklembacaklılara ne ad verilir?", d: "Trilobit", y: ["Ammonit", "Amonyak"], a: "Trilobitler 250 milyon yılı aşkın bir süre denizlerde yaşadı. Fosilleri çok yaygındır ve kayaçların yaşını belirlemede kullanılır." },
  { id: "p06-280", k: "Doğa", s: "Böcek, örümcek ve yengeçlerin ortak özelliği hangisidir?", d: "Eklemli bacak ve dış iskelet", y: ["Omurga ve kıkırdak", "Akciğer ve kabuk"], a: "Bu hayvanların hepsi eklembacaklılar şubesindedir. Vücutları sert bir dış iskeletle örtülüdür ve bacakları eklemlidir." },
  { id: "p06-281", k: "Doğa", s: "Hayvanlar aleminde bilinen tür sayısı en fazla olan şube hangisidir?", d: "Eklembacaklılar", y: ["Omurgalılar", "Yumuşakçalar"], a: "Böcekleri, örümceğimsileri ve kabukluları içeren eklembacaklılar, bilinen hayvan türlerinin büyük çoğunluğunu oluşturur." },
  { id: "p06-282", k: "Doğa", s: "Böceklerin kanatları vücudun hangi bölümüne bağlıdır?", d: "Göğüs", y: ["Baş", "Karın"], a: "Kanatlar ve bacaklar böceğin orta bölümü olan göğse bağlıdır. Göğüs, uçuş kaslarıyla doludur." },
  { id: "p06-283", k: "Doğa", s: "Böceklerin vücudunda dolaşan kan benzeri sıvıya ne denir?", d: "Hemolenf", y: ["Plazma", "Lenf düğümü"], a: "Hemolenf böceklerde genellikle renksiz, sarımsı ya da yeşilimsidir. Oksijeni pek taşımaz, çünkü hava doğrudan soluk borularıyla dokulara gider." },
  { id: "p06-284", k: "Doğa", s: "Böceklerin dolaşım sistemi hangi tiptedir?", d: "Açık dolaşım", y: ["Kapalı dolaşım", "Çift dolaşım"], a: "Böceklerde hemolenf damarlar içinde kalmaz, organların arasındaki boşluklarda dolaşır. Sırttaki boru biçimli kalp onu ileri doğru pompalar." },
  { id: "p06-285", k: "Doğa", s: "Tırtıllar hangi böceklerin larvasıdır?", d: "Kelebek ve güvelerin", y: ["Arı ve karıncaların", "Sinek ve sivrisineklerin"], a: "Tırtıllar kelebek ve güvelerin larvalarıdır. Yaşamlarının bu evresinde neredeyse sürekli yaprak yiyerek büyürler." },
  { id: "p06-286", k: "Doğa", s: "Kurtçuk (bacaksız beyaz larva) en çok hangi böceğin larvasına verilen addır?", d: "Sinek", y: ["Kelebek", "Örümcek"], a: "Sinek larvaları bacaksız, beyazımsı kurtçuklardır. Çürüyen maddelerde gelişir, sonra pupa olup ergin sineğe dönüşürler." },
  { id: "p06-287", k: "Doğa", s: "Kâğıt eşekarıları yuvalarını hangi malzemeden yapar?", d: "Çiğnenmiş odun liflerinden", y: ["Balmumundan", "Çamurdan"], a: "Eşekarıları odun liflerini kemirip tükürükle karıştırır. Bu hamurdan kâğıda benzeyen petekli yuvalar yaparlar." },
  { id: "p06-288", k: "Doğa", s: "Eşekarıları bal arılarından farklı olarak neyi yapabilir?", d: "Defalarca sokabilir", y: ["Bal üretebilir", "Balmumu salgılayabilir"], a: "Eşekarısının iğnesi düzdür, deriye takılıp kopmaz. Bu yüzden aynı eşekarısı birkaç kez sokabilir." },
  { id: "p06-289", k: "Doğa", s: "Bazı böceklerin su yüzeyinde batmadan yürümesini sağlayan olay hangisidir?", d: "Yüzey gerilimi", y: ["Kaldırma kuvveti", "Manyetizma"], a: "Su yüzeyi ince bir zar gibi davranır. Su üstünde yürüyen böceklerin ayakları su itici kıllarla kaplıdır, ağırlıklarını yüzeye yayarlar." },
  { id: "p06-290", k: "Doğa", s: "Çubuk böcekleri düşmanlarından nasıl korunur?", d: "Dala benzeyerek", y: ["Zehir püskürterek", "Yüksek ses çıkararak"], a: "Çubuk böceklerinin ince uzun gövdesi ve bacakları kuru dallara çok benzer. Rüzgârda sallanan dal gibi hafifçe sallanabilirler bile." },
  { id: "p06-291", k: "Doğa", s: "Bombardıman böceği tehlikede ne yapar?", d: "Kaynar sıcaklıkta kimyasal püskürtür", y: ["Ölü taklidi yaparken parlar", "Kanatlarını koparıp bırakır"], a: "Bombardıman böceğinin karnında iki kimyasal karışınca şiddetli bir tepkime olur. Böcek bu kaynar ve yakıcı sıvıyı düşmanına fışkırtır." },
  { id: "p06-292", k: "Doğa", s: "İncir ağaçlarının tozlaşmasını hangi böcek sağlar?", d: "İncir arısı", y: ["Bal arısı", "Uğur böceği"], a: "Minik incir arıları incirin içindeki çiçeklere girip yumurtlar ve polen taşır. İncir ağaçları ile incir arıları birbirine bağımlıdır." },
  { id: "p06-293", k: "Doğa", s: "Sel basan ateş karıncaları kolonilerini nasıl kurtarır?", d: "Birbirine kenetlenip sal oluşturur", y: ["Su altında nefes tutar", "Ağaç tepelerine yuva yapar"], a: "Ateş karıncaları bacak ve çeneleriyle birbirine tutunarak su üstünde yüzen canlı bir sal kurar. Kraliçe ve yavrular salın ortasında korunur." },
  { id: "p06-294", k: "Doğa", s: "Bazı termit türleri yuvalarının içini serin tutmak için ne yapar?", d: "Havalandırma kanalları olan tepeler yapar", y: ["Göl kenarına taşınır", "Kış uykusuna yatar"], a: "Afrika'daki bazı termitlerin topraktan yaptığı yüksek tepelerde çok sayıda kanal bulunur. Bu kanallar hava dolaşımını sağlayıp yuvanın sıcaklığını dengeler." },
  { id: "p06-295", k: "Doğa", s: "Kelebek ve güvelerin kanatlarına dokununca parmağa geçen toz aslında nedir?", d: "Kanat pulları", y: ["Çiçek tozu", "Kurumuş kan"], a: "Bu toz kanatlardaki minik pullardır. Pullar kopunca kanat zayıflar, bu yüzden kelebeklere dokunmamak iyidir." },
  { id: "p06-296", k: "Doğa", s: "Böcekler çevrelerini koku ve dokunmayla algılarken en çok hangi organı kullanır?", d: "Antenler", y: ["Kanatlar", "Karın"], a: "Antenler koku, dokunma ve bazen sıcaklık alıcılarıyla doludur. Birçok böcek eşini ve besinini antenleriyle bulur." },
  { id: "p06-297", k: "Doğa", s: "Böcekler büyürken dış iskeletlerini ne yapar?", d: "Deri değiştirerek yeniler", y: ["Esneterek genişletir", "Hiç büyümez"], a: "Sert dış iskelet büyüyemez. Böcek eskisini atar ve yenisi sertleşmeden önce vücudunu genişletir." },
  { id: "p06-298", k: "Doğa", s: "Hangisi bir böcek değildir, bir örümceğimsidir?", d: "Akar", y: ["Bit", "Pire"], a: "Akarlar sekiz bacaklıdır ve keneler gibi örümceğimsiler grubundadır. Bit ve pire ise altı bacaklı böceklerdir." },
];
